    CONSTRAINT uk_rail_section_id UNIQUE (section_id)
);
COMMENT ON TABLE rail_section IS '既有线路区段表；区段长度用于按气象限速推算最低运行分钟数';
COMMENT ON COLUMN rail_section.id IS '主键';
COMMENT ON COLUMN rail_section.section_id IS '区段业务 ID，全局唯一，与占用 section_id 对应';
COMMENT ON COLUMN rail_section.section_name IS '区段名称';
COMMENT ON COLUMN rail_section.length_meters IS '区段长度，单位米，必须为正';
COMMENT ON COLUMN rail_section.created_at IS '创建时刻，UTC 毫秒';

CREATE TABLE IF NOT EXISTS speed_restriction_order (
    id BIGINT NOT NULL AUTO_INCREMENT,
    order_key VARCHAR(64) NOT NULL,
    version INT NOT NULL,
    section_id VARCHAR(64) NOT NULL,
    start_utc BIGINT,
    end_utc BIGINT,
    max_speed_kmh INT,
    status VARCHAR(16) NOT NULL,
    operator VARCHAR(64) NOT NULL,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_speed_order_key_version UNIQUE (order_key, version)
);
COMMENT ON TABLE speed_restriction_order IS '气象限速令版本表，行不可变；同一 order_key 追加新版本，登记/修订为 ACTIVE，撤销追加 REVOKED 行';
COMMENT ON COLUMN speed_restriction_order.id IS '主键';
COMMENT ON COLUMN speed_restriction_order.order_key IS '限速令业务键，全局唯一';
COMMENT ON COLUMN speed_restriction_order.version IS '令内版本号，从 1 开始单调递增';
COMMENT ON COLUMN speed_restriction_order.section_id IS '限速区段 ID，关联 rail_section.section_id；REVOKED 行保留撤销时的区段快照';
COMMENT ON COLUMN speed_restriction_order.start_utc IS '限速开始时刻（含），UTC 毫秒；REVOKED 撤销标记行该字段为 NULL，表示无适用窗口';
COMMENT ON COLUMN speed_restriction_order.end_utc IS '限速结束时刻（不含），UTC 毫秒，必须晚于 start_utc；REVOKED 行为 NULL';
COMMENT ON COLUMN speed_restriction_order.max_speed_kmh IS '最高允许速度，公里/小时，范围 10～300；REVOKED 行为 NULL';
COMMENT ON COLUMN speed_restriction_order.status IS '版本状态：ACTIVE 生效 / REVOKED 已撤销；同一令以最新版本状态为准';
COMMENT ON COLUMN speed_restriction_order.operator IS '操作者标识；SYSTEM 表示由系统/未显式携带操作者的操作写入';
COMMENT ON COLUMN speed_restriction_order.created_at IS '版本写入时刻，UTC 毫秒';
CREATE INDEX IF NOT EXISTS idx_speed_order_section ON speed_restriction_order (section_id, status);

CREATE TABLE IF NOT EXISTS speed_version_seq (
    id INT NOT NULL,
    version BIGINT NOT NULL,
    PRIMARY KEY (id)
);
COMMENT ON TABLE speed_version_seq IS '限速令全局版本序列（单行），在全局写锁内推进；发布/改签在锁内读取，作为重排依据与幂等指纹';
COMMENT ON COLUMN speed_version_seq.id IS '固定为 1';
COMMENT ON COLUMN speed_version_seq.version IS '限速令当前全局版本，初始 0，每次登记/修订/撤销提交时加一';

CREATE TABLE IF NOT EXISTS rail_reschedule_record (
    id BIGINT NOT NULL AUTO_INCREMENT,
    record_key VARCHAR(160) NOT NULL,
    trigger_op VARCHAR(32) NOT NULL,
    request_key VARCHAR(128) NOT NULL,
    speed_version BIGINT NOT NULL,
    operator VARCHAR(64) NOT NULL,
    delay_minutes BIGINT NOT NULL,
    plan_count INT NOT NULL,
    created_at BIGINT NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT uk_rail_reschedule_record_key UNIQUE (record_key)
);
COMMENT ON TABLE rail_reschedule_record IS '气象限速重排历史证据主表，仅在批内存在正顺延量时写入，写入后任何限速令撤销/修订或计划操作均不得改写';
COMMENT ON COLUMN rail_reschedule_record.id IS '主键';
COMMENT ON COLUMN rail_reschedule_record.record_key IS '重排记录业务键，操作类型与 requestKey 拼接，全局唯一';
COMMENT ON COLUMN rail_reschedule_record.trigger_op IS '触发操作：PUBLISH / RESCHEDULE / PUBLISH_BATCH / RESCHEDULE_BATCH';
COMMENT ON COLUMN rail_reschedule_record.request_key IS '触发请求的幂等键';
COMMENT ON COLUMN rail_reschedule_record.speed_version IS '本次重排固化使用的限速令全局版本，后续限速变化不影响本记录';
COMMENT ON COLUMN rail_reschedule_record.operator IS '操作者标识；SYSTEM 表示请求未显式携带操作者';
COMMENT ON COLUMN rail_reschedule_record.delay_minutes IS '本批最大整体顺延分钟数（按线路最小间隔向上取整），大于 0 才会产生记录';
COMMENT ON COLUMN rail_reschedule_record.plan_count IS '批内计划数量';
COMMENT ON COLUMN rail_reschedule_record.created_at IS '重排提交时刻，UTC 毫秒';

CREATE TABLE IF NOT EXISTS rail_reschedule_item (
    id BIGINT NOT NULL AUTO_INCREMENT,
    record_id BIGINT NOT NULL,
    plan_seq INT NOT NULL,
    schedule_key VARCHAR(64) NOT NULL,
    section_seq INT NOT NULL,
    train_no VARCHAR(64) NOT NULL,
    section_id VARCHAR(64) NOT NULL,
    old_start_utc BIGINT NOT NULL,
    old_end_utc BIGINT NOT NULL,
    new_start_utc BIGINT NOT NULL,
    new_end_utc BIGINT NOT NULL,
    delay_minutes BIGINT NOT NULL,
    actual_minutes BIGINT NOT NULL,
    affected_minutes BIGINT NOT NULL,
    required_minutes BIGINT NOT NULL,
    hit_order_key VARCHAR(64),
    hit_order_version INT,
    PRIMARY KEY (id),
    CONSTRAINT uk_rail_reschedule_item_seq UNIQUE (record_id, plan_seq, section_seq)
);
COMMENT ON TABLE rail_reschedule_item IS '重排历史逐段不可变明细，按 record_id、plan_seq、section_seq 稳定排序';
COMMENT ON COLUMN rail_reschedule_item.id IS '主键';
COMMENT ON COLUMN rail_reschedule_item.record_id IS '所属重排记录 id，关联 rail_reschedule_record.id';
COMMENT ON COLUMN rail_reschedule_item.plan_seq IS '批内计划序号，从 0 开始，按请求列表顺序';
COMMENT ON COLUMN rail_reschedule_item.schedule_key IS '该段所属计划业务键';
COMMENT ON COLUMN rail_reschedule_item.section_seq IS '段在原计划占用清单内的序号（seq），从 0 开始';
COMMENT ON COLUMN rail_reschedule_item.train_no IS '列车编号';
COMMENT ON COLUMN rail_reschedule_item.section_id IS '区段 ID';
COMMENT ON COLUMN rail_reschedule_item.old_start_utc IS '顺延前段开始时刻（含），UTC 毫秒';
COMMENT ON COLUMN rail_reschedule_item.old_end_utc IS '顺延前段结束时刻（不含），UTC 毫秒';
COMMENT ON COLUMN rail_reschedule_item.new_start_utc IS '顺延后段开始时刻（含），UTC 毫秒，等于 old_start_utc 加 delay_minutes';
COMMENT ON COLUMN rail_reschedule_item.new_end_utc IS '顺延后段结束时刻（不含），UTC 毫秒，等于 old_end_utc 加 delay_minutes';
COMMENT ON COLUMN rail_reschedule_item.delay_minutes IS '该计划整体顺延分钟数（批内单调不减，按线路最小间隔取整）';
COMMENT ON COLUMN rail_reschedule_item.actual_minutes IS '原时刻表该段实际运行分钟数（时长取整分钟）';
COMMENT ON COLUMN rail_reschedule_item.affected_minutes IS '原运行时刻落入限速窗口（左闭右开交集）的受影响运行分钟数';
COMMENT ON COLUMN rail_reschedule_item.required_minutes IS '按命中限速与区段长度推算的要求运行分钟数（含取整），大于 actual_minutes 即原时刻违反限速';
COMMENT ON COLUMN rail_reschedule_item.hit_order_key IS '决定该段顺延量的最低速限速令业务键；NULL 表示该段自身未命中限速，仅随批内前序计划整体顺延';
COMMENT ON COLUMN rail_reschedule_item.hit_order_version IS '命中限速令版本号；NULL 含义同 hit_order_key';

MERGE INTO publish_lock KEY(id) VALUES (1);
MERGE INTO speed_version_seq KEY(id) VALUES (1, 0);

