package com.example.starter.plan.repo;

import com.example.starter.plan.model.RailSection;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/**
 * 既有线路区段持久化。区段为线路基础数据，长度供限速运行分钟推算使用。
 */
@Repository
public class RailSectionRepository {

    private static final RowMapper<RailSection> MAPPER = (rs, n) -> new RailSection(
            rs.getLong("id"),
            rs.getString("section_id"),
            rs.getString("section_name"),
            rs.getLong("length_meters"),
            rs.getLong("created_at"));

    private final JdbcTemplate jdbc;

    public RailSectionRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 登记既有区段，返回自增主键。
     */
    public long insert(String sectionId, String sectionName, long lengthMeters, long nowMillis) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO rail_section (section_id, section_name, length_meters, created_at)"
                            + " VALUES (?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, sectionId);
            ps.setString(2, sectionName);
            ps.setLong(3, lengthMeters);
            ps.setLong(4, nowMillis);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    /**
     * 按区段业务 ID 查询。
     */
    public Optional<RailSection> findBySectionId(String sectionId) {
        return jdbc.query("SELECT id, section_id, section_name, length_meters, created_at"
                        + " FROM rail_section WHERE section_id = ?",
                MAPPER, sectionId).stream().findFirst();
    }

    /**
     * 列出全部区段，按业务 ID 稳定排序。
     */
    public List<RailSection> findAll() {
        return jdbc.query("SELECT id, section_id, section_name, length_meters, created_at"
                + " FROM rail_section ORDER BY section_id", MAPPER);
    }
}

