package com.example.starter.plan.repo;

import com.example.starter.plan.model.ActiveRestriction;
import com.example.starter.plan.model.SpeedOrderStatus;
import com.example.starter.plan.model.SpeedOrderVersion;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.Instant;
import java.util.Collection;
import java.util.List;
import java.util.Optional;
import java.util.StringJoiner;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/**
 * 版本化气象限速令持久化。版本行只追加、不修改、不删除；
 * ACTIVE 行窗口速度非空，REVOKED 行窗口速度为空。
 */
@Repository
public class SpeedRestrictionRepository {

    private static final RowMapper<SpeedOrderVersion> VERSION_MAPPER = (rs, n) -> new SpeedOrderVersion(
            rs.getLong("id"),
            rs.getString("order_key"),
            rs.getInt("version"),
            rs.getString("section_id"),
            rs.getObject("start_utc") == null ? null : Instant.ofEpochMilli(rs.getLong("start_utc")),
            rs.getObject("end_utc") == null ? null : Instant.ofEpochMilli(rs.getLong("end_utc")),
            rs.getObject("max_speed_kmh") == null ? null : rs.getInt("max_speed_kmh"),
            SpeedOrderStatus.valueOf(rs.getString("status")),
            rs.getString("operator"),
            rs.getLong("created_at"));

    private final JdbcTemplate jdbc;

    public SpeedRestrictionRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 追加限速令版本行（登记/修订 ACTIVE，撤销 REVOKED），返回自增主键。
     */
    public long insertVersion(String orderKey, int version, String sectionId, Instant startUtc,
                              Instant endUtc, Integer maxSpeedKmh, SpeedOrderStatus status,
                              String operator, long nowMillis) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO speed_restriction_order"
                            + " (order_key, version, section_id, start_utc, end_utc, max_speed_kmh,"
                            + " status, operator, created_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, orderKey);
            ps.setInt(2, version);
            ps.setString(3, sectionId);
            if (startUtc == null) {
                ps.setNull(4, java.sql.Types.BIGINT);
            } else {
                ps.setLong(4, startUtc.toEpochMilli());
            }
            if (endUtc == null) {
                ps.setNull(5, java.sql.Types.BIGINT);
            } else {
                ps.setLong(5, endUtc.toEpochMilli());
            }
            if (maxSpeedKmh == null) {
                ps.setNull(6, java.sql.Types.INTEGER);
            } else {
                ps.setInt(6, maxSpeedKmh);
            }
            ps.setString(7, status.name());
            ps.setString(8, operator);
            ps.setLong(9, nowMillis);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    /**
     * 查询某令全部版本行，按版本号升序。
     */
    public List<SpeedOrderVersion> findVersions(String orderKey) {
        return jdbc.query("SELECT id, order_key, version, section_id, start_utc, end_utc,"
                        + " max_speed_kmh, status, operator, created_at"
                        + " FROM speed_restriction_order WHERE order_key = ? ORDER BY version",
                VERSION_MAPPER, orderKey);
    }

    /**
     * 查询某令最新版本（版本号最大）。
     */
    public Optional<SpeedOrderVersion> findLatestVersion(String orderKey) {
        return jdbc.query("SELECT id, order_key, version, section_id, start_utc, end_utc,"
                        + " max_speed_kmh, status, operator, created_at"
                        + " FROM speed_restriction_order WHERE order_key = ?"
                        + " ORDER BY version DESC LIMIT 1",
                VERSION_MAPPER, orderKey).stream().findFirst();
    }

    /**
     * 查询某令最新版本并加行锁，须在事务（全局写锁）内调用。
     */
    public Optional<SpeedOrderVersion> findLatestVersionForUpdate(String orderKey) {
        return jdbc.query("SELECT id, order_key, version, section_id, start_utc, end_utc,"
                        + " max_speed_kmh, status, operator, created_at"
                        + " FROM speed_restriction_order WHERE order_key = ?"
                        + " ORDER BY version DESC LIMIT 1 FOR UPDATE",
                VERSION_MAPPER, orderKey).stream().findFirst();
    }

    /**
     * 读取并锁定全局版本序列当前值。
     */
    public long currentVersionForUpdate() {
        return jdbc.queryForObject("SELECT version FROM speed_version_seq WHERE id = 1 FOR UPDATE",
                Long.class);
    }

    /**
     * 设置全局版本序列值。
     */
    public void updateGlobalVersion(long version) {
        jdbc.update("UPDATE speed_version_seq SET version = ? WHERE id = 1", version);
    }

    /**
     * 查询指定区段集合上当前 ACTIVE 限速（仅保留每令最新版本行），
     * 按区段、窗口开始、令键稳定排序。
     */
    public List<ActiveRestriction> findActiveBySections(Collection<String> sectionIds) {
        if (sectionIds.isEmpty()) {
            return List.of();
        }
        StringJoiner placeholders = new StringJoiner(", ");
        sectionIds.forEach(s -> placeholders.add("?"));
        return jdbc.query("SELECT t.order_key, t.version, t.section_id, t.start_utc, t.end_utc,"
                        + " t.max_speed_kmh, t.operator FROM speed_restriction_order t"
                        + " WHERE t.status = 'ACTIVE' AND t.section_id IN (" + placeholders + ")"
                        + " AND t.version = (SELECT MAX(s.version) FROM speed_restriction_order s"
                        + " WHERE s.order_key = t.order_key)"
                        + " ORDER BY t.section_id, t.start_utc, t.order_key",
                (rs, n) -> new ActiveRestriction(
                        rs.getString("order_key"),
                        rs.getInt("version"),
                        rs.getString("section_id"),
                        Instant.ofEpochMilli(rs.getLong("start_utc")),
                        Instant.ofEpochMilli(rs.getLong("end_utc")),
                        rs.getInt("max_speed_kmh"),
                        rs.getString("operator")),
                sectionIds.toArray());
    }
}

