package com.example.starter.plan.repo;

import com.example.starter.plan.model.RescheduleItem;
import com.example.starter.plan.model.RescheduleRecord;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.Instant;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Repository;

/**
 * 气象限速重排历史证据持久化。主表与逐段明细表只追加、不修改、不删除；
 * 所有读取按 (plan_seq, section_seq) 稳定排序，时间字段保持 UTC 毫秒精度。
 */
@Repository
public class RescheduleRecordRepository {

    private static final RowMapper<RescheduleRecord> RECORD_MAPPER = (rs, n) -> new RescheduleRecord(
            rs.getLong("id"),
            rs.getString("record_key"),
            rs.getString("trigger_op"),
            rs.getString("request_key"),
            rs.getLong("speed_version"),
            rs.getString("operator"),
            rs.getLong("delay_minutes"),
            rs.getInt("plan_count"),
            rs.getLong("created_at"));

    private static final RowMapper<RescheduleItem> ITEM_MAPPER = (rs, n) -> new RescheduleItem(
            rs.getLong("id"),
            rs.getLong("record_id"),
            rs.getInt("plan_seq"),
            rs.getString("schedule_key"),
            rs.getInt("section_seq"),
            rs.getString("train_no"),
            rs.getString("section_id"),
            Instant.ofEpochMilli(rs.getLong("old_start_utc")),
            Instant.ofEpochMilli(rs.getLong("old_end_utc")),
            Instant.ofEpochMilli(rs.getLong("new_start_utc")),
            Instant.ofEpochMilli(rs.getLong("new_end_utc")),
            rs.getLong("delay_minutes"),
            rs.getLong("actual_minutes"),
            rs.getLong("affected_minutes"),
            rs.getLong("required_minutes"),
            rs.getString("hit_order_key"),
            rs.getObject("hit_order_version") == null ? null : rs.getInt("hit_order_version"));

    private final JdbcTemplate jdbc;

    public RescheduleRecordRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /**
     * 插入重排主记录，返回自增主键。
     */
    public long insertRecord(String recordKey, String triggerOp, String requestKey, long speedVersion,
                             String operator, long delayMinutes, int planCount, long nowMillis) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO rail_reschedule_record"
                            + " (record_key, trigger_op, request_key, speed_version, operator,"
                            + " delay_minutes, plan_count, created_at)"
                            + " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, recordKey);
            ps.setString(2, triggerOp);
            ps.setString(3, requestKey);
            ps.setLong(4, speedVersion);
            ps.setString(5, operator);
            ps.setLong(6, delayMinutes);
            ps.setInt(7, planCount);
            ps.setLong(8, nowMillis);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    /**
     * 按业务键查询重排主记录。
     */
    public Optional<RescheduleRecord> findByRecordKey(String recordKey) {
        return jdbc.query("SELECT id, record_key, trigger_op, request_key, speed_version, operator,"
                        + " delay_minutes, plan_count, created_at"
                        + " FROM rail_reschedule_record WHERE record_key = ?",
                RECORD_MAPPER, recordKey).stream().findFirst();
    }

    /**
     * 查询某计划（按业务键）参与过的全部重排记录，按提交时刻、id 升序。
     */
    public List<RescheduleRecord> findRecordsByPlanKey(String scheduleKey) {
        return jdbc.query("SELECT DISTINCT r.id, r.record_key, r.trigger_op, r.request_key,"
                        + " r.speed_version, r.operator, r.delay_minutes, r.plan_count, r.created_at"
                        + " FROM rail_reschedule_record r JOIN rail_reschedule_item i"
                        + " ON i.record_id = r.id WHERE i.schedule_key = ?"
                        + " ORDER BY r.created_at, r.id",
                RECORD_MAPPER, scheduleKey);
    }

    /**
     * 查询某重排记录的全部逐段明细，按批内计划序号、段序号稳定排序。
     */
    public List<RescheduleItem> findItems(long recordId) {
        return jdbc.query("SELECT id, record_id, plan_seq, schedule_key, section_seq, train_no,"
                        + " section_id, old_start_utc, old_end_utc, new_start_utc, new_end_utc,"
                        + " delay_minutes, actual_minutes, affected_minutes, required_minutes,"
                        + " hit_order_key, hit_order_version"
                        + " FROM rail_reschedule_item WHERE record_id = ?"
                        + " ORDER BY plan_seq, section_seq",
                ITEM_MAPPER, recordId);
    }

    /**
     * 批量追加逐段明细。
     */
    public void insertItems(List<RescheduleItem> items) {
        jdbc.batchUpdate(
                "INSERT INTO rail_reschedule_item"
                        + " (record_id, plan_seq, schedule_key, section_seq, train_no, section_id,"
                        + " old_start_utc, old_end_utc, new_start_utc, new_end_utc, delay_minutes,"
                        + " actual_minutes, affected_minutes, required_minutes, hit_order_key,"
                        + " hit_order_version)"
                        + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                items, items.size(),
                (ps, it) -> {
                    ps.setLong(1, it.recordId());
                    ps.setInt(2, it.planSeq());
                    ps.setString(3, it.scheduleKey());
                    ps.setInt(4, it.sectionSeq());
                    ps.setString(5, it.trainNo());
                    ps.setString(6, it.sectionId());
                    ps.setLong(7, it.oldStartUtc().toEpochMilli());
                    ps.setLong(8, it.oldEndUtc().toEpochMilli());
                    ps.setLong(9, it.newStartUtc().toEpochMilli());
                    ps.setLong(10, it.newEndUtc().toEpochMilli());
                    ps.setLong(11, it.delayMinutes());
                    ps.setLong(12, it.actualMinutes());
                    ps.setLong(13, it.affectedMinutes());
                    ps.setLong(14, it.requiredMinutes());
                    if (it.hitOrderKey() == null) {
                        ps.setNull(15, java.sql.Types.VARCHAR);
                    } else {
                        ps.setString(15, it.hitOrderKey());
                    }
                    if (it.hitOrderVersion() == null) {
                        ps.setNull(16, java.sql.Types.INTEGER);
                    } else {
                        ps.setInt(16, it.hitOrderVersion());
                    }
                });
    }
}

