package com.example.starter.plan.service;

import com.example.starter.plan.model.ActiveRestriction;
import com.example.starter.plan.model.Occupancy;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * 气象限速顺延引擎（纯计算，无 IO），发布/改签批量裁决共用。
 *
 * <p>模型约定（UTC 左闭右开）：
 * <ul>
 *   <li>逐段判断：占用与限速窗口有交集，且原时刻表该段运行分钟数小于按区段长度与限速
 *       （长度公里 × 60 ÷ 限速，向上取整）推算的要求分钟数时，原运行时刻违反限速；</li>
 *   <li>同一区段同一时刻多条命令叠加时，以最低速度（要求分钟数最大者）为准；</li>
 *   <li>顺延只向后：将占用整体平移到其开始时刻不早于限速窗口结束（相邻即可），
 *       顺延分钟数按线路最小间隔向上取整；</li>
 *   <li>批内顺延量单调不减：后续关联计划至少继承前序计划顺延量，并在平移后重新判定，
 *       防止被推进后来的限速窗口；</li>
 *   <li>引擎同时负责顺延后的运营日越界、已开始运行与时隙冲突判定，产出稳定排序的问题明细。</li>
 * </ul>
 */
public final class SpeedShiftEngine {

    private static final long MINUTE_MILLIS = 60_000L;

    private SpeedShiftEngine() {
    }

    /**
     * 批内一个裁决单元：批量发布为一张待发布草稿；批量改签为一张新草稿（旧计划取消不参与平移）。
     *
     * @param planSeq     批内序号，从 0 开始
     * @param scheduleKey 计划业务键
     * @param occupancies 原时刻表占用（按 seq 升序）
     */
    public record ShiftUnit(int planSeq, String scheduleKey, List<Occupancy> occupancies) {
    }

    /**
     * 单段评估证据。
     *
     * @param sectionSeq       段序号
     * @param delayMinutes     所属计划整体顺延分钟数
     * @param actualMinutes    原时刻表运行分钟数
     * @param affectedMinutes  原时刻与限速窗口并集的交集分钟数
     * @param requiredMinutes  最低速命中令推算的要求运行分钟数；未命中令时等于 actualMinutes
     * @param hitOrderKey      最低速命中令键；未命中为 null
     * @param hitOrderVersion  命中令版本；未命中为 null
     */
    public record SectionEval(int sectionSeq, long delayMinutes, long actualMinutes,
                              long affectedMinutes, long requiredMinutes, String hitOrderKey,
                              Integer hitOrderVersion) {
    }

    /**
     * 单计划评估结果。
     */
    public record UnitResult(String scheduleKey, long delayMinutes, List<Occupancy> shifted,
                             List<SectionEval> evals) {
    }

    /**
     * 引擎输入。
     *
     * @param units           批内有序单元
     * @param restrictions    锁内快照的全部当前生效限速令
     * @param sectionLengths  区段长度（米），仅登记过的区段可能命中限速
     * @param now             判定“已开始运行”的当前时刻（可控时钟）
     * @param dayStart        运营日开始（含），UTC
     * @param dayEnd          运营日结束（不含），UTC
     * @param headwayMinutes  线路最小间隔分钟数（顺延对齐粒度）
     * @param externalSlots   批外已发布计划的生效时隙（已排除本批新旧计划）
     */
    public record ShiftInput(List<ShiftUnit> units, List<ActiveRestriction> restrictions,
                             Map<String, Long> sectionLengths, Instant now, Instant dayStart,
                             Instant dayEnd, long headwayMinutes,
                             List<com.example.starter.plan.model.PublishedSlot> externalSlots) {
    }

    /**
     * 引擎输出。
     *
     * @param results  与输入同序的逐计划结果
     * @param problems 稳定排序的问题明细（空表示可提交）
     */
    public record ShiftOutput(List<UnitResult> results, List<Map<String, Object>> problems) {

        public long maxDelayMinutes() {
            return results.stream().mapToLong(UnitResult::delayMinutes).max().orElse(0L);
        }
    }

    /**
     * 执行顺延评估。
     */
    public static ShiftOutput evaluate(ShiftInput input) {
        Map<String, List<ActiveRestriction>> bySection = groupBySection(input.restrictions());
        List<Map<String, Object>> problems = new ArrayList<>();
        List<UnitResult> results = new ArrayList<>();
        long inherited = 0L;

        // 已在批内确定的顺延后时隙，用于同批后续计划冲突裁决
        List<Slot> committedSlots = new ArrayList<>();

        for (ShiftUnit unit : input.units()) {
            long delay = resolveDelay(unit, input, bySection, inherited);
            List<Occupancy> shifted = shiftAll(unit, delay);

            validateStartedAndDay(unit, delay, shifted, input, problems);
            validateTrainOverlap(unit, shifted, problems);
            validateExternalConflicts(unit, shifted, input, problems);
            validateBatchConflicts(unit, shifted, committedSlots, problems);

            List<SectionEval> evals = buildEvals(unit, delay, input, bySection);
            results.add(new UnitResult(unit.scheduleKey(), delay, shifted, evals));
            for (Occupancy o : shifted) {
                committedSlots.add(new Slot(unit.scheduleKey(), o.sectionId(),
                        o.startUtc(), o.endUtc()));
            }
            inherited = Math.max(inherited, delay);
        }

        problems.sort(PROBLEM_ORDER);
        return new ShiftOutput(results, problems);
    }

    // ---------- 顺延量求解 ----------

    private static long resolveDelay(ShiftUnit unit, ShiftInput input,
                                     Map<String, List<ActiveRestriction>> bySection,
                                     long inherited) {
        long delay = inherited;
        // 定点迭代：平移后可能落入后续限速窗口，单调推进至稳定。
        for (int guard = 0; guard < 64; guard++) {
            long raised = delay;
            for (Occupancy o : unit.occupancies()) {
                long actual = durationMinutes(o.startUtc(), o.endUtc());
                Instant shiftedStart = o.startUtc().plusMillis(delay * MINUTE_MILLIS);
                Instant shiftedEnd = o.endUtc().plusMillis(delay * MINUTE_MILLIS);
                for (ActiveRestriction r : bySection.getOrDefault(o.sectionId(), List.of())) {
                    if (!overlaps(shiftedStart, shiftedEnd, r.startUtc(), r.endUtc())) {
                        continue;
                    }
                    Long length = input.sectionLengths().get(o.sectionId());
                    if (length == null) {
                        continue;
                    }
                    long required = requiredMinutes(length, r.maxSpeedKmh());
                    if (actual >= required) {
                        continue;
                    }
                    // 须将该段平移至限速窗口结束之后（开始时刻相邻窗口结束即可）
                    long rawMillis = Math.max(0L, r.endUtc().toEpochMilli() - o.startUtc().toEpochMilli());
                    long rawMinutes = ceilMinutes(rawMillis);
                    long need = ceilToHeadway(rawMinutes, input.headwayMinutes());
                    raised = Math.max(raised, need);
                }
            }
            if (raised == delay) {
                return delay;
            }
            delay = raised;
        }
        throw new IllegalStateException("顺延量迭代未收敛: " + unit.scheduleKey());
    }

    private static List<SectionEval> buildEvals(ShiftUnit unit, long delay, ShiftInput input,
                                                Map<String, List<ActiveRestriction>> bySection) {
        List<SectionEval> evals = new ArrayList<>();
        for (Occupancy o : unit.occupancies()) {
            long actual = durationMinutes(o.startUtc(), o.endUtc());
            List<ActiveRestriction> hits = overlappingAtOriginal(o,
                    bySection.getOrDefault(o.sectionId(), List.of()), input.sectionLengths());
            if (hits.isEmpty()) {
                evals.add(new SectionEval(o.seq(), delay, actual, 0L, actual, null, null));
                continue;
            }
            ActiveRestriction slowest = hits.stream()
                    .min(Comparator.comparingInt(ActiveRestriction::maxSpeedKmh)
                            .thenComparing(ActiveRestriction::orderKey))
                    .orElseThrow();
            long required = requiredMinutes(input.sectionLengths().get(o.sectionId()),
                    slowest.maxSpeedKmh());
            long affected = unionOverlapMinutes(o, hits);
            evals.add(new SectionEval(o.seq(), delay, actual, affected, required,
                    slowest.orderKey(), slowest.version()));
        }
        return evals;
    }

    private static List<ActiveRestriction> overlappingAtOriginal(
            Occupancy o, List<ActiveRestriction> candidates, Map<String, Long> lengths) {
        if (!lengths.containsKey(o.sectionId())) {
            return List.of();
        }
        long actual = durationMinutes(o.startUtc(), o.endUtc());
        List<ActiveRestriction> hits = new ArrayList<>();
        for (ActiveRestriction r : candidates) {
            if (overlaps(o.startUtc(), o.endUtc(), r.startUtc(), r.endUtc())
                    && actual < requiredMinutes(lengths.get(o.sectionId()), r.maxSpeedKmh())) {
                hits.add(r);
            }
        }
        return hits;
    }

    /**
     * 占用与限速窗口并集的交集分钟数，多令重叠不重复计分钟。
     */
    private static long unionOverlapMinutes(Occupancy o, List<ActiveRestriction> restrictions) {
        List<long[]> intervals = new ArrayList<>();
        for (ActiveRestriction r : restrictions) {
            long from = Math.max(o.startUtc().toEpochMilli(), r.startUtc().toEpochMilli());
            long to = Math.min(o.endUtc().toEpochMilli(), r.endUtc().toEpochMilli());
            if (from < to) {
                intervals.add(new long[]{from, to});
            }
        }
        intervals.sort(Comparator.comparingLong(a -> a[0]));
        long millis = 0L;
        long mergedEnd = Long.MIN_VALUE;
        long mergedStart = 0L;
        for (long[] iv : intervals) {
            if (iv[0] > mergedEnd) {
                millis += mergedEnd - mergedStart;
                mergedStart = iv[0];
                mergedEnd = iv[1];
            } else {
                mergedEnd = Math.max(mergedEnd, iv[1]);
            }
        }
        if (mergedEnd != Long.MIN_VALUE) {
            millis += mergedEnd - mergedStart;
        }
        return millis / MINUTE_MILLIS;
    }

    // ---------- 校验 ----------

    private static void validateStartedAndDay(ShiftUnit unit, long delay, List<Occupancy> shifted,
                                              ShiftInput input, List<Map<String, Object>> problems) {
        Instant earliest = shifted.stream().map(Occupancy::startUtc).min(Instant::compareTo)
                .orElseThrow();
        if (delay > 0 && !input.now().isBefore(earliest.minusMillis(delay * MINUTE_MILLIS))) {
            // 原计划最早开始时刻已到/已过：已开始运行的计划不可重排
            Instant originalStart = earliest.minusMillis(delay * MINUTE_MILLIS);
            Map<String, Object> p = baseProblem("PLAN_ALREADY_STARTED", unit.scheduleKey(),
                    null, originalStart, earliest);
            p.put("actualUtc", input.now().toString());
            p.put("requiredStartAfterUtc", originalStart.toString());
            p.put("delayMinutes", delay);
            problems.add(p);
        }
        for (Occupancy o : shifted) {
            if (o.endUtc().isAfter(input.dayEnd()) || o.startUtc().isBefore(input.dayStart())) {
                long overrunMillis = Math.max(0L,
                        o.endUtc().toEpochMilli() - input.dayEnd().toEpochMilli());
                Map<String, Object> p = baseProblem("SHIFT_OUT_OF_DAY", unit.scheduleKey(),
                        o.sectionId(), o.startUtc(), o.endUtc());
                p.put("requiredEndBeforeUtc", input.dayEnd().toString());
                p.put("overrunMinutes", ceilMinutes(overrunMillis));
                p.put("delayMinutes", delay);
                p.put("trainNo", o.trainNo());
                problems.add(p);
            }
        }
    }

    private static void validateTrainOverlap(ShiftUnit unit, List<Occupancy> shifted,
                                             List<Map<String, Object>> problems) {
        Map<String, List<Occupancy>> byTrain = new LinkedHashMap<>();
        for (Occupancy o : shifted) {
            byTrain.computeIfAbsent(o.trainNo(), k -> new ArrayList<>()).add(o);
        }
        byTrain.forEach((trainNo, list) -> {
            List<Occupancy> sorted = list.stream()
                    .sorted(Comparator.comparingInt(Occupancy::seq)).toList();
            for (int i = 1; i < sorted.size(); i++) {
                Occupancy prev = sorted.get(i - 1);
                Occupancy cur = sorted.get(i);
                if (cur.startUtc().isBefore(prev.endUtc())) {
                    Map<String, Object> p = baseProblem("TRAIN_OVERLAP", unit.scheduleKey(),
                            cur.sectionId(), cur.startUtc(), cur.endUtc());
                    p.put("trainNo", trainNo);
                    problems.add(p);
                }
            }
        });
    }

    private static void validateExternalConflicts(ShiftUnit unit, List<Occupancy> shifted,
                                                  ShiftInput input,
                                                  List<Map<String, Object>> problems) {
        for (Occupancy o : shifted) {
            for (com.example.starter.plan.model.PublishedSlot slot : input.externalSlots()) {
                if (!o.sectionId().equals(slot.sectionId())) {
                    continue;
                }
                if (overlaps(o.startUtc(), o.endUtc(), slot.startUtc(), slot.endUtc())) {
                    Map<String, Object> p = baseProblem("SECTION_CONFLICT", unit.scheduleKey(),
                            o.sectionId(), o.startUtc(), o.endUtc());
                    p.put("conflictingScheduleKey", slot.scheduleKey());
                    p.put("trainNo", o.trainNo());
                    problems.add(p);
                }
            }
        }
    }

    private static void validateBatchConflicts(ShiftUnit unit, List<Occupancy> shifted,
                                               List<Slot> committedSlots,
                                               List<Map<String, Object>> problems) {
        for (Occupancy o : shifted) {
            for (Slot slot : committedSlots) {
                if (!o.sectionId().equals(slot.sectionId())) {
                    continue;
                }
                if (overlaps(o.startUtc(), o.endUtc(), slot.startUtc(), slot.endUtc())) {
                    Map<String, Object> p = baseProblem("BATCH_SHIFT_CONFLICT", unit.scheduleKey(),
                            o.sectionId(), o.startUtc(), o.endUtc());
                    p.put("conflictingScheduleKey", slot.scheduleKey());
                    p.put("trainNo", o.trainNo());
                    problems.add(p);
                }
            }
        }
    }

    // ---------- 共用工具 ----------

    private static List<Occupancy> shiftAll(ShiftUnit unit, long delayMinutes) {
        List<Occupancy> result = new ArrayList<>(unit.occupancies().size());
        for (Occupancy o : unit.occupancies()) {
            result.add(new Occupancy(o.id(), o.planId(), o.seq(), o.trainNo(), o.sectionId(),
                    o.startUtc().plusMillis(delayMinutes * MINUTE_MILLIS),
                    o.endUtc().plusMillis(delayMinutes * MINUTE_MILLIS)));
        }
        return result;
    }

    private static Map<String, List<ActiveRestriction>> groupBySection(
            List<ActiveRestriction> restrictions) {
        Map<String, List<ActiveRestriction>> map = new LinkedHashMap<>();
        List<ActiveRestriction> sorted = restrictions.stream()
                .sorted(Comparator.comparing(ActiveRestriction::sectionId)
                        .thenComparing(ActiveRestriction::startUtc)
                        .thenComparing(ActiveRestriction::orderKey))
                .toList();
        for (ActiveRestriction r : sorted) {
            map.computeIfAbsent(r.sectionId(), k -> new ArrayList<>()).add(r);
        }
        return map;
    }

    private static Map<String, Object> baseProblem(String type, String scheduleKey, String sectionId,
                                                   Instant start, Instant end) {
        Map<String, Object> p = new LinkedHashMap<>();
        p.put("type", type);
        p.put("scheduleKey", scheduleKey);
        if (sectionId != null) {
            p.put("sectionId", sectionId);
        }
        p.put("startUtc", start.toString());
        p.put("endUtc", end.toString());
        return p;
    }

    private static boolean overlaps(Instant aStart, Instant aEnd, Instant bStart, Instant bEnd) {
        return aStart.isBefore(bEnd) && bStart.isBefore(aEnd);
    }

    private static long durationMinutes(Instant start, Instant end) {
        return Duration.between(start, end).toMillis() / MINUTE_MILLIS;
    }

    /** 按区段长度（米）与限速（公里/小时）推算要求运行分钟数，向上取整。 */
    public static long requiredMinutes(long lengthMeters, int maxSpeedKmh) {
        long millis = (long) Math.ceil(lengthMeters * 3600.0 / (maxSpeedKmh * 1000.0) * 1000.0);
        return Math.max(1L, ceilMinutes(millis));
    }

    private static long ceilMinutes(long millis) {
        return (millis + MINUTE_MILLIS - 1) / MINUTE_MILLIS;
    }

    private static long ceilToHeadway(long minutes, long headwayMinutes) {
        if (minutes <= 0L) {
            return 0L;
        }
        return ((minutes + headwayMinutes - 1) / headwayMinutes) * headwayMinutes;
    }

    private record Slot(String scheduleKey, String sectionId, Instant startUtc, Instant endUtc) {
    }

    /** 问题明细稳定排序：类型、计划、区段、开始时刻、冲突计划。 */
    private static final Comparator<Map<String, Object>> PROBLEM_ORDER = Comparator
            .comparing((Map<String, Object> p) -> (String) p.get("type"))
            .thenComparing(p -> (String) p.get("scheduleKey"))
            .thenComparing(p -> String.valueOf(p.getOrDefault("sectionId", "")))
            .thenComparing(p -> (String) p.get("startUtc"))
            .thenComparing(p -> String.valueOf(p.getOrDefault("conflictingScheduleKey", "")));
}

