package com.example.starter.plan.service;

import java.time.Clock;
import java.time.Instant;
import org.springframework.stereotype.Component;

/**
 * 统一时钟：业务判定“当前时刻”（如计划是否已开始运行）只经此组件读取。
 * 默认跟随系统 UTC 时钟；测试可 {@link #pinTo(Instant)} 固定时刻并在结束后 {@link #reset()}。
 */
@Component
public class RailClock {

    private volatile Clock clock = Clock.systemUTC();

    /**
     * 当前时刻，UTC。
     */
    public Instant now() {
        return Instant.now(clock);
    }

    /**
     * 当前 UTC 毫秒。
     */
    public long nowMillis() {
        return now().toEpochMilli();
    }

    /**
     * 固定到指定时刻，仅测试使用。
     */
    public void pinTo(Instant instant) {
        this.clock = Clock.fixed(instant, java.time.ZoneOffset.UTC);
    }

    /**
     * 恢复系统 UTC 时钟，仅测试使用。
     */
    public void reset() {
        this.clock = Clock.systemUTC();
    }
}

package com.example.starter.plan.service;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * 线路排程参数。
 */
@Component
public class RailProperties {

    /**
     * 线路既有最小发车间隔（分钟）；气象限速顺延量必须按该值向上取整对齐。
     */
    private final long headwayMinutes;

    public RailProperties(@Value("${rail.headway-minutes:5}") long headwayMinutes) {
        if (headwayMinutes <= 0) {
            throw new IllegalArgumentException("rail.headway-minutes 必须为正: " + headwayMinutes);
        }
        this.headwayMinutes = headwayMinutes;
    }

    public long headwayMinutes() {
        return headwayMinutes;
    }
}

