package com.example.starter.plan.service;

import com.example.starter.plan.model.ActiveRestriction;
import com.example.starter.plan.model.RailSection;
import com.example.starter.plan.model.SpeedOrderStatus;
import com.example.starter.plan.model.SpeedOrderVersion;
import com.example.starter.plan.repo.IdempotencyRepository;
import com.example.starter.plan.repo.PlanRepository;
import com.example.starter.plan.repo.RailSectionRepository;
import com.example.starter.plan.repo.SpeedRestrictionRepository;
import com.example.starter.plan.web.ApiException;
import com.example.starter.plan.web.dto.ActiveRestrictionView;
import com.example.starter.plan.web.dto.DiagnosticResponse;
import com.example.starter.plan.web.dto.RegisterSectionRequest;
import com.example.starter.plan.web.dto.RestrictionRegisterRequest;
import com.example.starter.plan.web.dto.RestrictionReviseRequest;
import com.example.starter.plan.web.dto.RestrictionRevokeRequest;
import com.example.starter.plan.web.dto.RestrictionVersionView;
import com.example.starter.plan.web.dto.SectionView;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * 线路区段登记与版本化气象限速令服务。
 *
 * <p>限速登记、修订、撤销均在全局发布锁内推进限速全局版本，因此与计划发布/改签严格按
 * 事务提交顺序裁决；版本行只追加，撤销与后续修订均不改写历史。写操作按
 * (操作类型, requestKey) 幂等：同键同参重放首次结果，异参 409，失败不占键。
 */
@Service
public class RestrictionService {

    /** 操作者缺省标识。 */
    public static final String SYSTEM_OPERATOR = "SYSTEM";

    static final int MIN_SPEED_KMH = 10;
    static final int MAX_SPEED_KMH = 300;

    private static final String OP_SECTION_REGISTER = "SECTION_REGISTER";
    private static final String OP_RESTRICTION_REGISTER = "RESTRICTION_REGISTER";
    private static final String OP_RESTRICTION_REVISE = "RESTRICTION_REVISE";
    private static final String OP_RESTRICTION_REVOKE = "RESTRICTION_REVOKE";

    private final RailSectionRepository sectionRepo;
    private final SpeedRestrictionRepository speedRepo;
    private final PlanRepository planRepo;
    private final IdempotencyRepository idemRepo;
    private final ObjectMapper objectMapper;
    private final RailClock clock;
    private final RailProperties properties;
    private final TransactionTemplate tx;

    public RestrictionService(RailSectionRepository sectionRepo, SpeedRestrictionRepository speedRepo,
                              PlanRepository planRepo, IdempotencyRepository idemRepo,
                              ObjectMapper objectMapper, RailClock clock, RailProperties properties,
                              PlatformTransactionManager txManager) {
        this.sectionRepo = sectionRepo;
        this.speedRepo = speedRepo;
        this.planRepo = planRepo;
        this.idemRepo = idemRepo;
        this.objectMapper = objectMapper;
        this.clock = clock;
        this.properties = properties;
        this.tx = new TransactionTemplate(txManager);
    }

    /**
     * 登记既有线路区段（长度单位米）。
     */
    public SectionView registerSection(RegisterSectionRequest req) {
        String operator = SYSTEM_OPERATOR;
        String hash = sha256(OP_SECTION_REGISTER + '\n' + req.sectionId() + '\n' + req.sectionName()
                + '\n' + req.lengthMeters());
        Optional<SectionView> replay = replay(OP_SECTION_REGISTER, req.requestKey(), hash,
                SectionView.class);
        if (replay.isPresent()) {
            return replay.get();
        }
        try {
            return tx.execute(status -> {
                if (sectionRepo.findBySectionId(req.sectionId()).isPresent()) {
                    throw conflict("SECTION_EXISTS", "区段已存在: " + req.sectionId());
                }
                long now = clock.nowMillis();
                sectionRepo.insert(req.sectionId(), req.sectionName(), req.lengthMeters(), now);
                idemRepo.insert(OP_SECTION_REGISTER, req.requestKey(), hash,
                        toJson(toView(req.sectionId(), req.sectionName(), req.lengthMeters())), now);
                return toView(req.sectionId(), req.sectionName(), req.lengthMeters());
            });
        } catch (DuplicateKeyException e) {
            return replay(OP_SECTION_REGISTER, req.requestKey(), hash, SectionView.class)
                    .orElseThrow(() -> conflict("SECTION_EXISTS", "区段已存在"));
        }
    }

    /**
     * 登记气象限速令版本 1。速度范围 10～300，未知区段或非法窗口返回 422；令键重复 409。
     */
    public RestrictionVersionView register(RestrictionRegisterRequest req) {
        validateWindowAndSpeed(req.startUtc(), req.endUtc(), req.maxSpeedKmh());
        String operator = normalizeOperator(req.operator());
        String hash = sha256(OP_RESTRICTION_REGISTER + '\n' + req.orderKey() + '\n'
                + req.sectionId() + '\n' + req.startUtc().toEpochMilli() + '\n'
                + req.endUtc().toEpochMilli() + '\n' + req.maxSpeedKmh() + '\n' + operator);
        Optional<RestrictionVersionView> replay =
                replay(OP_RESTRICTION_REGISTER, req.requestKey(), hash, RestrictionVersionView.class);
        if (replay.isPresent()) {
            return replay.get();
        }
        try {
            return tx.execute(status -> {
                planRepo.acquirePublishLock();
                if (speedRepo.findLatestVersion(req.orderKey()).isPresent()) {
                    throw conflict("RESTRICTION_KEY_EXISTS", "限速令已存在: " + req.orderKey());
                }
                RailSection section = sectionRepo.findBySectionId(req.sectionId())
                        .orElseThrow(() -> unprocessable("SECTION_NOT_FOUND",
                                "区段不存在: " + req.sectionId()));
                long now = clock.nowMillis();
                long globalVersion = speedRepo.currentVersionForUpdate() + 1;
                speedRepo.insertVersion(req.orderKey(), 1, section.sectionId(), req.startUtc(),
                        req.endUtc(), req.maxSpeedKmh(), SpeedOrderStatus.ACTIVE, operator, now);
                speedRepo.updateGlobalVersion(globalVersion);
                RestrictionVersionView view = toView(req.orderKey(), 1, section.sectionId(),
                        req.startUtc(), req.endUtc(), req.maxSpeedKmh(), SpeedOrderStatus.ACTIVE,
                        operator, now, globalVersion);
                idemRepo.insert(OP_RESTRICTION_REGISTER, req.requestKey(), hash, toJson(view), now);
                return view;
            });
        } catch (DuplicateKeyException e) {
            return replay(OP_RESTRICTION_REGISTER, req.requestKey(), hash,
                    RestrictionVersionView.class)
                    .orElseThrow(() -> conflict("RESTRICTION_KEY_EXISTS", "限速令已存在"));
        }
    }

    /**
     * 修订限速令：追加新的 ACTIVE 版本。仅最新版本 ACTIVE 的令可修订；非法窗口/速度 422。
     */
    public RestrictionVersionView revise(String orderKey, RestrictionReviseRequest req) {
        validateWindowAndSpeed(req.startUtc(), req.endUtc(), req.maxSpeedKmh());
        String operator = normalizeOperator(req.operator());
        String hash = sha256(OP_RESTRICTION_REVISE + '\n' + orderKey + '\n'
                + req.startUtc().toEpochMilli() + '\n' + req.endUtc().toEpochMilli() + '\n'
                + req.maxSpeedKmh() + '\n' + operator);
        Optional<RestrictionVersionView> replay =
                replay(OP_RESTRICTION_REVISE, req.requestKey(), hash, RestrictionVersionView.class);
        if (replay.isPresent()) {
            return replay.get();
        }
        return tx.execute(status -> {
            planRepo.acquirePublishLock();
            SpeedOrderVersion latest = speedRepo.findLatestVersion(orderKey)
                    .orElseThrow(() -> orderNotFound(orderKey));
            if (latest.status() != SpeedOrderStatus.ACTIVE) {
                throw conflict("RESTRICTION_NOT_ACTIVE",
                        "限速令已撤销，不可修订: " + orderKey);
            }
            long now = clock.nowMillis();
            int newVersion = latest.version() + 1;
            long globalVersion = speedRepo.currentVersionForUpdate() + 1;
            speedRepo.insertVersion(orderKey, newVersion, latest.sectionId(), req.startUtc(),
                    req.endUtc(), req.maxSpeedKmh(), SpeedOrderStatus.ACTIVE, operator, now);
            speedRepo.updateGlobalVersion(globalVersion);
            RestrictionVersionView view = toView(orderKey, newVersion, latest.sectionId(),
                    req.startUtc(), req.endUtc(), req.maxSpeedKmh(), SpeedOrderStatus.ACTIVE,
                    operator, now, globalVersion);
            idemRepo.insert(OP_RESTRICTION_REVISE, req.requestKey(), hash, toJson(view), now);
            return view;
        });
    }

    /**
     * 撤销限速令：追加 REVOKED 版本行（窗口/速度为 null），不删除历史；已撤销再撤销 409。
     * 撤销只影响后续发布或改签，不改写已固化的重排记录。
     */
    public RestrictionVersionView revoke(String orderKey, RestrictionRevokeRequest req) {
        String operator = normalizeOperator(req.operator());
        String hash = sha256(OP_RESTRICTION_REVOKE + '\n' + orderKey + '\n' + operator);
        Optional<RestrictionVersionView> replay =
                replay(OP_RESTRICTION_REVOKE, req.requestKey(), hash, RestrictionVersionView.class);
        if (replay.isPresent()) {
            return replay.get();
        }
        return tx.execute(status -> {
            planRepo.acquirePublishLock();
            SpeedOrderVersion latest = speedRepo.findLatestVersion(orderKey)
                    .orElseThrow(() -> orderNotFound(orderKey));
            if (latest.status() != SpeedOrderStatus.ACTIVE) {
                throw conflict("RESTRICTION_NOT_ACTIVE",
                        "限速令已撤销，不可重复撤销: " + orderKey);
            }
            long now = clock.nowMillis();
            int newVersion = latest.version() + 1;
            long globalVersion = speedRepo.currentVersionForUpdate() + 1;
            speedRepo.insertVersion(orderKey, newVersion, latest.sectionId(), null, null, null,
                    SpeedOrderStatus.REVOKED, operator, now);
            speedRepo.updateGlobalVersion(globalVersion);
            RestrictionVersionView view = toView(orderKey, newVersion, latest.sectionId(), null,
                    null, null, SpeedOrderStatus.REVOKED, operator, now, globalVersion);
            idemRepo.insert(OP_RESTRICTION_REVOKE, req.requestKey(), hash, toJson(view), now);
            return view;
        });
    }

    /**
     * 查询限速令全部不可变版本，按版本号升序；令不存在 404。
     */
    public List<RestrictionVersionView> getOrderDetail(String orderKey) {
        List<SpeedOrderVersion> versions = speedRepo.findVersions(orderKey);
        if (versions.isEmpty()) {
            throw orderNotFound(orderKey);
        }
        return versions.stream().map(v -> toView(v, globalVersionAt(v.createdAt()))).toList();
    }

    /**
     * 查询当前生效限速；sectionId 为空表示全部区段。同一区段同一时刻多条并列返回。
     */
    public List<ActiveRestrictionView> getActiveRestrictions(String sectionId) {
        List<String> sectionIds = sectionId == null || sectionId.isBlank()
                ? sectionRepo.findAll().stream().map(RailSection::sectionId).toList()
                : List.of(sectionId);
        return speedRepo.findActiveBySections(sectionIds).stream()
                .map(r -> new ActiveRestrictionView(r.orderKey(), r.version(), r.sectionId(),
                        r.startUtc(), r.endUtc(), r.maxSpeedKmh(), r.operator()))
