     */
    public Map<String, Long> loadSectionLengths() {
        Map<String, Long> map = new HashMap<>();
        for (RailSection s : sectionRepo.findAll()) {
            map.put(s.sectionId(), s.lengthMeters());
        }
        return map;
    }

    // ---------- 内部实现 ----------

    private void validateWindowAndSpeed(Instant startUtc, Instant endUtc, Integer maxSpeedKmh) {
        if (startUtc == null || endUtc == null || !endUtc.isAfter(startUtc)) {
            throw unprocessable("INVALID_RESTRICTION_WINDOW",
                    "限速时段非法：开始/结束不能为空且结束必须晚于开始（UTC 左闭右开）");
        }
