        // 精确值随版本行一同固化在视图场景中由写入方法直接给出；历史读取使用当前值不影响行内字段。
        return speedRepo.currentVersion();
    }

    private <T> Optional<T> replay(String opType, String requestKey, String hash, Class<T> type) {
        return idemRepo.find(opType, requestKey).map(record -> {
            if (!record.requestHash().equals(hash)) {
                throw conflict("IDEMPOTENT_KEY_REUSED",
                        "requestKey 已用于其他参数: " + requestKey);
            }
            return fromJson(record.responseJson(), type);
        });
    }

    private SectionView toView(String sectionId, String sectionName, long lengthMeters) {
        return new SectionView(sectionId, sectionName, lengthMeters);
    }

    private RestrictionVersionView toView(String orderKey, int version, String sectionId,
                                          Instant startUtc, Instant endUtc, Integer maxSpeedKmh,
                                          SpeedOrderStatus status, String operator, long createdAtMillis,
                                          long globalVersion) {
        return new RestrictionVersionView(orderKey, version, sectionId, startUtc, endUtc,
                maxSpeedKmh, status.name(), operator, Instant.ofEpochMilli(createdAtMillis),
                globalVersion);
    }

    private RestrictionVersionView toView(SpeedOrderVersion v, long globalVersion) {
        return new RestrictionVersionView(v.orderKey(), v.version(), v.sectionId(), v.startUtc(),
                v.endUtc(), v.maxSpeedKmh(), v.status().name(), v.operator(),
                Instant.ofEpochMilli(v.createdAt()), globalVersion);
    }

    private String toJson(Object response) {
        try {
            return objectMapper.writeValueAsString(response);
        } catch (Exception e) {
            throw new IllegalStateException("响应序列化失败", e);
        }
    }

    private <T> T fromJson(String json, Class<T> type) {
        try {
            return objectMapper.readValue(json, type);
        } catch (Exception e) {
            throw new IllegalStateException("幂等响应反序列化失败", e);
        }
    }

    private String sha256(String text) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashed = digest.digest(text.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(hashed.length * 2);
            for (byte b : hashed) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
                hex.append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private ApiException unprocessable(String code, String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, code, message);
    }

    private ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }

    private ApiException orderNotFound(String orderKey) {
        return new ApiException(HttpStatus.NOT_FOUND, "RESTRICTION_NOT_FOUND",
                "限速令不存在: " + orderKey);
    }
}

