                    RestrictionVersionView.class)
                    .orElseThrow(() -> conflict("RESTRICTION_KEY_EXISTS", "限速令已存在"));
        }
    }

    /**
     * 修订限速令：追加新的 ACTIVE 版本。仅最新版本 ACTIVE 的令可修订；非法窗口/速度 422。
     */
    public RestrictionVersionView revise(String orderKey, RestrictionReviseRequest req) {
        validateWindowAndSpeed(req.startUtc(), req.endUtc(), req.maxSpeedKmh());
        String operator = normalizeOperator(req.operator());
