// ---------- 内部实现 ----------

private void validateWindowAndSpeed(Instant startUtc, Instant endUtc, Integer maxSpeedKmh) {
    if (startUtc == null || endUtc == null || !endUtc.isAfter(startUtc)) {
        throw unprocessable("INVALID_RESTRICTION_WINDOW",
                "限速时段非法：开始/结束不能为空且结束必须晚于开始（UTC 左闭右开）");
    }
    if (maxSpeedKmh == null || maxSpeedKmh < MIN_SPEED_KMH || maxSpeedKmh > MAX_SPEED_KMH) {
        throw unprocessable("INVALID_RESTRICTION_SPEED",
                "限速速度非法：要求值 " + MIN_SPEED_KMH + "～" + MAX_SPEED_KMH + " km/h"
                        + (maxSpeedKmh == null ? "，实际值缺失" : "，实际值 " + maxSpeedKmh));
    }
}

private String normalizeOperator(String operator) {
    return operator == null || operator.isBlank() ? SYSTEM_OPERATOR : operator.trim();
}

private String normalizeOperator(String operator) {
    return idemRepo.find(opType, requestKey).map(record -> {
        if (!record.requestHash().equals(hash)) {
            throw conflict("IDEMPOTENT_KEY_REUSED",
                    "requestKey 已用于其他参数: " + requestKey);
        }
        return fromJson(record.responseJson(), type);
    });
}

