package com.example.starter.plan.web.dto;

import jakarta.validation.constraints.NotBlank;
import java.time.Instant;

/**
 * 气象限速令登记请求。区间左闭右开 [startUtc, endUtc)，UTC 为统一时间口径；
 * maxSpeedKmh 合法范围 10～300（公里/小时）。窗口、速度或区段非法由业务层返回 422。
 * operator 可空，缺省记为 SYSTEM。
 */
