package com.example.starter.plan.service;

import com.example.starter.plan.model.DayPlan;
import com.example.starter.plan.model.Occupancy;
import com.example.starter.plan.model.PlanStatus;
import com.example.starter.plan.model.PublishedSlot;
import com.example.starter.plan.model.RescheduleItem;
import com.example.starter.plan.model.RescheduleLink;
import com.example.starter.plan.model.RescheduleRecord;
import com.example.starter.plan.repo.IdempotencyRepository;
import com.example.starter.plan.repo.PlanRepository;
import com.example.starter.plan.repo.RescheduleRecordRepository;
import com.example.starter.plan.repo.SpeedRestrictionRepository;
import com.example.starter.plan.web.ApiException;
import com.example.starter.plan.web.dto.BatchPlanResponse;
import com.example.starter.plan.web.dto.BatchRescheduleResponse;
import com.example.starter.plan.web.dto.CreatePlanRequest;
import com.example.starter.plan.web.dto.OccupancyRequest;
import com.example.starter.plan.web.dto.OccupancyView;
import com.example.starter.plan.web.dto.PlanResponse;
import com.example.starter.plan.web.dto.PublishBatchRequest;
import com.example.starter.plan.web.dto.PublishedSlotView;
import com.example.starter.plan.web.dto.RescheduleBatchRequest;
import com.example.starter.plan.web.dto.RescheduleChainItem;
import com.example.starter.plan.web.dto.RescheduleChainResponse;
import com.example.starter.plan.web.dto.RescheduleDetailResponse;
import com.example.starter.plan.web.dto.RescheduleItemView;
import com.example.starter.plan.web.dto.RescheduleRecordView;
import com.example.starter.plan.web.dto.RescheduleRequest;
import com.example.starter.plan.web.dto.RescheduleResponse;
import com.example.starter.plan.web.dto.UpdateOccupanciesRequest;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeSet;
import java.util.stream.Collectors;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * 铁路走廊日计划核心业务：草稿创建/整体替换、发布、取消、原子改签与查询，
 * 以及气象限速下的批量发布/批量改签与整体顺延。
 *
 * <p>并发与幂等约定：写操作按 (操作类型, requestKey) 幂等，同键同参重放返回首次成功结果，
 * 同键不同参返回 409；限速登记/撤销/修订、发布与改签共用全局发布锁，严格按事务提交顺序裁决；
 * 同一计划的更新/发布/取消/改签另经行锁串行化，并发改签与重排不会产生两套生效时刻。
 * 仅成功结果写入幂等记录，失败（含 422）不缓存、可修正后重试。
 *
 * <p>顺延证据：批内存在正顺延量时，在同一事务固化重排主记录与逐段明细（限速全局版本、
 * 操作者、原/新时刻、实际/受影响/要求分钟数与命中限速令），此后任何操作不改写该证据。
 */
@Service
public class PlanService {

    /** 运营日解释时区。 */
    public static final ZoneId OPERATION_ZONE = ZoneId.of("Asia/Shanghai");

    private static final String OP_CREATE = "CREATE";
    private static final String OP_UPDATE = "UPDATE";
    private static final String OP_PUBLISH = "PUBLISH";
    private static final String OP_CANCEL = "CANCEL";
    private static final String OP_RESCHEDULE = "RESCHEDULE";
    private static final String OP_PUBLISH_BATCH = "PUBLISH_BATCH";
    private static final String OP_RESCHEDULE_BATCH = "RESCHEDULE_BATCH";

    private final PlanRepository planRepo;
    private final IdempotencyRepository idemRepo;
    private final SpeedRestrictionRepository speedRepo;
    private final RescheduleRecordRepository recordRepo;
    private final RestrictionService restrictionService;
    private final ObjectMapper objectMapper;
    private final RailClock clock;
    private final RailProperties properties;
    private final TransactionTemplate tx;

    public PlanService(PlanRepository planRepo, IdempotencyRepository idemRepo,
                       SpeedRestrictionRepository speedRepo, RescheduleRecordRepository recordRepo,
                       RestrictionService restrictionService, ObjectMapper objectMapper,
                       RailClock clock, RailProperties properties,
                       PlatformTransactionManager txManager) {
        this.planRepo = planRepo;
        this.idemRepo = idemRepo;
        this.speedRepo = speedRepo;
        this.recordRepo = recordRepo;
        this.restrictionService = restrictionService;
        this.objectMapper = objectMapper;
        this.clock = clock;
        this.properties = properties;
        this.tx = new TransactionTemplate(txManager);
    }

    /**
     * 创建草稿计划（版本 1，状态 DRAFT）。
     */
    public PlanResponse createDraft(CreatePlanRequest req) {
        validateOccupancyParams(req.occupancies());
        validateWithinOperationDay(req.occupancies(), req.opDate());
        String hash = hashCreate(req);
        Optional<PlanResponse> replay = replayIfPresent(OP_CREATE, req.requestKey(), hash);
        if (replay.isPresent()) {
            return replay.get();
        }
        try {
            return tx.execute(status -> {
                if (planRepo.findByKey(req.scheduleKey()).isPresent()) {
                    throw conflict("SCHEDULE_KEY_EXISTS", "scheduleKey 已存在: " + req.scheduleKey());
                }
                long now = clock.nowMillis();
                long planId = planRepo.insertPlan(req.scheduleKey(), req.opDate(), PlanStatus.DRAFT, now);
                planRepo.insertOccupancies(planId, toOccupancies(planId, req.occupancies()));
                PlanResponse response = loadPlan(req.scheduleKey());
                idemRepo.insert(OP_CREATE, req.requestKey(), hash, toJson(response), now);
                return response;
            });
        } catch (DuplicateKeyException e) {
            return resolveDuplicate(OP_CREATE, req.requestKey(), hash);
        }
    }

    /**
     * 整体替换草稿占用清单，版本加一；仅 DRAFT 可改，expectedVersion 必须匹配。
     */
    public PlanResponse replaceOccupancies(String scheduleKey, UpdateOccupanciesRequest req) {
        validateOccupancyParams(req.occupancies());
        String hash = hashUpdate(scheduleKey, req);
        Optional<PlanResponse> replay = replayIfPresent(OP_UPDATE, req.requestKey(), hash);
        if (replay.isPresent()) {
            return replay.get();
        }
        try {
            return tx.execute(status -> {
                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
                        .orElseThrow(() -> notFound(scheduleKey));
                if (plan.status() != PlanStatus.DRAFT) {
                    throw conflict("PLAN_STATE_CONFLICT",
                            "仅草稿可修改占用，当前状态: " + plan.status());
                }
                if (req.expectedVersion() != plan.version()) {
                    throw conflict("VERSION_CONFLICT",
                            "expectedVersion=" + req.expectedVersion() + " 与当前版本 " + plan.version() + " 不一致");
                }
                validateWithinOperationDay(req.occupancies(), plan.opDate());
                long now = clock.nowMillis();
                planRepo.replaceOccupancies(plan.id(), toOccupancies(plan.id(), req.occupancies()));
                planRepo.updateVersionAndStatus(plan.id(), plan.version() + 1, PlanStatus.DRAFT, now);
                PlanResponse response = loadPlan(scheduleKey);
                idemRepo.insert(OP_UPDATE, req.requestKey(), hash, toJson(response), now);
                return response;
            });
        } catch (DuplicateKeyException e) {
            return resolveDuplicate(OP_UPDATE, req.requestKey(), hash);
        }
    }

    /**
     * 发布计划：全局发布锁内按当前限速评估并整体顺延，再原子校验列车重叠与区段冲突，
     * 任一问题整张计划保持草稿并抛出 422（携带稳定排序的冲突/顺延问题明细）。
     */
    public PlanResponse publish(String scheduleKey, String requestKey) {
        String hash = hashAction(OP_PUBLISH, scheduleKey);
        Optional<PlanResponse> replay = replayIfPresent(OP_PUBLISH, requestKey, hash);
        if (replay.isPresent()) {
            return replay.get();
        }
        try {
            return tx.execute(status -> {
                PublishOutcome outcome = executePublish(
                        List.of(new PublishEntry(scheduleKey, null)),
                        RestrictionService.SYSTEM_OPERATOR, OP_PUBLISH);
                PlanResponse response = outcome.plans().get(0);
                idemRepo.insert(OP_PUBLISH, requestKey, hash, toJson(response),
                                clock.nowMillis());
                return response;
            });
        } catch (DuplicateKeyException e) {
            return resolveDuplicate(OP_PUBLISH, requestKey, hash);
        }
    }

    /**
     * 批量发布：按列表顺序在同一事务、同一批次内评估限速顺延与冲突，全部成功才统一提交，
     * 任一计划问题整批 422 且无任何半成品。
     */
    public BatchPlanResponse publishBatch(PublishBatchRequest req) {
        List<String> keys = req.scheduleKeys();
        String operator = normalizeOperator(req.operator());
        validateDistinctKeys(keys);
        String hash = hashKeyList(OP_PUBLISH_BATCH, keys, operator);
        Optional<BatchPlanResponse> replay =
                replayIfPresent(OP_PUBLISH_BATCH, req.requestKey(), hash, BatchPlanResponse.class);
        if (replay.isPresent()) {
            return replay.get();
        }
        return tx.execute(status -> {
            List<PublishEntry> entries = keys.stream().map(k -> new PublishEntry(k, null)).toList();
            PublishOutcome outcome = executePublish(entries, operator, OP_PUBLISH_BATCH);
            BatchPlanResponse response = new BatchPlanResponse(outcome.speedVersion(), operator,
                    outcome.maxDelayMinutes(), properties.headwayMinutes(), outcome.plans(),
                    outcome.delays(), outcome.recordKey(), clock.now());
            idemRepo.insert(OP_PUBLISH_BATCH, req.requestKey(), hash, toJson(response),
                    clock.nowMillis());
            return response;
        });
    }

    /**
     * 取消已发布计划：时隙立即释放，历史计划与占用保留不改写。
     */
    public PlanResponse cancel(String scheduleKey, String requestKey) {
        String hash = hashAction(OP_CANCEL, scheduleKey);
        Optional<PlanResponse> replay = replayIfPresent(OP_CANCEL, requestKey, hash);
        if (replay.isPresent()) {
            return replay.get();
        }
        try {
            return tx.execute(status -> {
                DayPlan plan = planRepo.findByKeyForUpdate(scheduleKey)
                        .orElseThrow(() -> notFound(scheduleKey));
                if (plan.status() != PlanStatus.PUBLISHED) {
                    throw conflict("PLAN_STATE_CONFLICT",
                            "仅已发布计划可取消，当前状态: " + plan.status());
                }
                long now = clock.nowMillis();
                planRepo.updateStatus(plan.id(), PlanStatus.CANCELLED, now);
                PlanResponse response = loadPlan(scheduleKey);
                idemRepo.insert(OP_CANCEL, requestKey, hash, toJson(response), now);
                return response;
            });
        } catch (DuplicateKeyException e) {
            return resolveDuplicate(OP_CANCEL, requestKey, hash);
        }
    }

    /**
     * 原子改签：全局发布锁内对新草稿按当前限速整体顺延并校验冲突，
     * 通过后同一事务取消旧计划、发布新计划、追加不可变前后继关联并固化重排证据。
     * 任一步失败整体回滚：旧计划仍发布、新计划仍草稿，版本、占用、关联与重排记录均不改变。
     */
    public RescheduleResponse reschedule(String oldScheduleKey, RescheduleRequest req) {
        if (oldScheduleKey.equals(req.newScheduleKey())) {
            throw badRequest("新旧计划必须不同: " + oldScheduleKey);
        }
        String hash = hashReschedule(oldScheduleKey, req);
        Optional<RescheduleResponse> replay =
                replayIfPresent(OP_RESCHEDULE, req.requestKey(), hash, RescheduleResponse.class);
        if (replay.isPresent()) {
            return replay.get();
        }
        try {
            return tx.execute(status -> {
                RescheduleOutcome outcome = executeReschedule(List.of(new RescheduleEntry(
                        oldScheduleKey, req.newScheduleKey(), req.expectedOldVersion(),
                        req.expectedNewVersion())), RestrictionService.SYSTEM_OPERATOR,
                        OP_RESCHEDULE);
                RescheduleResponse response = outcome.pairs().get(0);
                idemRepo.insert(OP_RESCHEDULE, req.requestKey(), hash, toJson(response),
                        clock.nowMillis());
                return response;
            });
        } catch (DuplicateKeyException e) {
            return replayIfPresent(OP_RESCHEDULE, req.requestKey(), hash, RescheduleResponse.class)
                    .orElseThrow(() -> conflict("LINK_CONFLICT", "改签前后继关联冲突"));
        }
    }

    /**
     * 批量原子改签：按列表顺序在同一事务取消旧计划、发布（必要时顺延）新草稿，
     * 任一校验失败整批 422/409 回滚，无半成品。
     */
    public BatchRescheduleResponse rescheduleBatch(RescheduleBatchRequest req) {
        String operator = normalizeOperator(req.operator());
        List<RescheduleBatchRequest.BatchRescheduleItem> items = req.items();
        validateRescheduleItems(items);
        List<String> oldKeys = items.stream().map(RescheduleBatchRequest.BatchRescheduleItem::oldScheduleKey).toList();
        List<String> newKeys = items.stream().map(RescheduleBatchRequest.BatchRescheduleItem::newScheduleKey).toList();
        String hash = hashRescheduleBatch(OP_RESCHEDULE_BATCH, items, operator);
        Optional<BatchRescheduleResponse> replay =
                replayIfPresent(OP_RESCHEDULE_BATCH, req.requestKey(), hash,
                        BatchRescheduleResponse.class);
        if (replay.isPresent()) {
            return replay.get();
        }
        return tx.execute(status -> {
            List<RescheduleEntry> entries = items.stream()
                    .map(i -> new RescheduleEntry(i.oldScheduleKey(), i.newScheduleKey(),
                            i.expectedOldVersion(), i.expectedNewVersion()))
                    .toList();
            RescheduleOutcome outcome = executeReschedule(entries, operator, OP_RESCHEDULE_BATCH);
            BatchRescheduleResponse response = new BatchRescheduleResponse(outcome.speedVersion(),
                    operator, outcome.maxDelayMinutes(), properties.headwayMinutes(),
                    outcome.pairs(), outcome.newDelays(), outcome.recordKey(), clock.now());
            idemRepo.insert(OP_RESCHEDULE_BATCH, req.requestKey(), hash, toJson(response),
                    clock.nowMillis());
            return response;
        });
    }

    /**
     * 查询包含指定计划在内的完整有序改签链（从最前驱到最后继）；
     * 无改签历史的计划链中仅含自身。计划不存在返回 404。
     */
    public RescheduleChainResponse getRescheduleChain(String scheduleKey) {
        DayPlan plan = planRepo.findByKey(scheduleKey)
                .orElseThrow(() -> notFound(scheduleKey));
        List<DayPlan> predecessors = new ArrayList<>();
        DayPlan cursor = plan;
        while (true) {
            Optional<RescheduleLink> link = planRepo.findLinkBySuccessor(cursor.id());
            if (link.isEmpty()) {
                break;
            }
            cursor = planRepo.findById(link.get().predecessorPlanId())
                    .orElseThrow(() -> new IllegalStateException("改签链前驱缺失: " + link.get()));
            predecessors.add(cursor);
        }
        Collections.reverse(predecessors);
        List<DayPlan> chain = new ArrayList<>(predecessors);
        chain.add(plan);
        cursor = plan;
        while (true) {
            Optional<RescheduleLink> link = planRepo.findLinkByPredecessor(cursor.id());
            if (link.isEmpty()) {
                break;
            }
            cursor = planRepo.findById(link.get().successorPlanId())
                    .orElseThrow(() -> new IllegalStateException("改签链后继缺失: " + link.get()));
            chain.add(cursor);
        }
        List<RescheduleChainItem> chainItems = chain.stream()
                .map(p -> new RescheduleChainItem(p.scheduleKey(), p.opDate(), p.version(),
                        p.status().name()))
                .toList();
        return new RescheduleChainResponse(scheduleKey, chainItems);
    }

    /**
     * 按计划业务键查询明细（含历史占用），不存在返回 404。
     */
    public PlanResponse getPlan(String scheduleKey) {
        if (planRepo.findByKey(scheduleKey).isEmpty()) {
            throw notFound(scheduleKey);
        }
        return loadPlan(scheduleKey);
    }

    /**
     * 查询指定运营日与区段上当前已发布的生效时隙（只读，不改变状态）。
     */
    public List<PublishedSlotView> getPublishedSlots(LocalDate opDate, String sectionId) {
        return planRepo.findPublishedSlots(opDate, List.of(sectionId), List.of(-1L)).stream()
                .map(s -> new PublishedSlotView(s.scheduleKey(), s.trainNo(), s.sectionId(),
                        s.startUtc(), s.endUtc()))
                .toList();
    }

    /**
     * 查询某计划参与过的全部气象限速重排记录摘要，按提交时间升序（只读）。
     */
    public List<RescheduleRecordView> getRescheduleHistory(String scheduleKey) {
        if (planRepo.findByKey(scheduleKey).isEmpty()) {
            throw notFound(scheduleKey);
        }
        return recordRepo.findRecordsByPlanKey(scheduleKey).stream()
                .map(this::toRecordView)
                .toList();
    }

    /**
     * 按重排记录业务键查询不可变证据详情（主记录加逐段明细），不存在 404（只读）。
     */
    public RescheduleDetailResponse getRescheduleDetail(String recordKey) {
        RescheduleRecord record = recordRepo.findByRecordKey(recordKey)
                .orElseThrow(() -> new ApiException(HttpStatus.NOT_FOUND, "RESCHEDULE_RECORD_NOT_FOUND",
                        "重排记录不存在: " + recordKey));
        List<RescheduleItemView> items = recordRepo.findItems(record.id()).stream()
                .map(this::toItemView)
                .toList();
        return new RescheduleDetailResponse(toRecordView(record), items);
    }

    // ---------- 批量发布/改签核心（须在已获取全局发布锁的事务内执行） ----------

    private record PublishEntry(String scheduleKey, Void unused) {
    }

    private record PublishOutcome(List<PlanResponse> plans, List<Long> delays, long speedVersion,
                                  long maxDelayMinutes, String recordKey) {
    }

    private record RescheduleEntry(String oldScheduleKey, String newScheduleKey,
                                   int expectedOldVersion, int expectedNewVersion) {
    }

    private record RescheduleOutcome(List<RescheduleResponse> pairs, List<Long> newDelays,
                                     long speedVersion, long maxDelayMinutes, String recordKey) {
    }

    private PublishOutcome executePublish(List<PublishEntry> entries, String operator,
                                          String triggerOp) {
        planRepo.acquirePublishLock();
        long speedVersion = speedRepo.currentVersionForUpdate();

        List<LockedPlan> locked = new ArrayList<>();
        for (PublishEntry entry : entries) {
            DayPlan plan = planRepo.findByKeyForUpdate(entry.scheduleKey())
                    .orElseThrow(() -> notFound(entry.scheduleKey()));
            if (plan.status() != PlanStatus.DRAFT) {
                throw conflict("PLAN_STATE_CONFLICT",
                        "仅草稿可发布，计划 " + entry.scheduleKey() + " 当前状态: " + plan.status());
            }
            locked.add(new LockedPlan(plan, planRepo.findOccupancies(plan.id())));
        }
        requireSameOpDate(locked.stream().map(l -> l.plan()).toList());

        List<Long> excludeIds = locked.stream().map(l -> l.plan().id()).toList();
        SpeedShiftEngine.ShiftOutput output = evaluateShift(locked, excludeIds);
        if (!output.problems().isEmpty()) {
            throw slotConflict(output.problems(), "存在时隙冲突或无法在运营日内完成顺延，发布未生效");
        }

        long now = clock.nowMillis();
        List<PlanResponse> plans = new ArrayList<>();
        List<Long> delays = new ArrayList<>();
        for (int i = 0; i < locked.size(); i++) {
            LockedPlan lp = locked.get(i);
            SpeedShiftEngine.UnitResult result = output.results().get(i);
            applyShiftIfNeeded(lp, result.shifted(), result.delayMinutes(), now);
            planRepo.updateStatus(lp.plan().id(), PlanStatus.PUBLISHED, now);
            delays.add(result.delayMinutes());
            plans.add(loadPlan(lp.plan().scheduleKey()));
        }
        String recordKey = persistRescheduleRecord(triggerOp, locked, output, speedVersion,
                operator, now);
        return new PublishOutcome(plans, delays, speedVersion, output.maxDelayMinutes(), recordKey);
    }

    private RescheduleOutcome executeReschedule(List<RescheduleEntry> entries, String operator,
                                                String triggerOp) {
        planRepo.acquirePublishLock();
        long speedVersion = speedRepo.currentVersionForUpdate();

        List<LockedPlan> locked = new ArrayList<>();
        List<DayPlan> oldPlans = new ArrayList<>();
        for (RescheduleEntry entry : entries) {
            DayPlan oldPlan = planRepo.findByKeyForUpdate(entry.oldScheduleKey())
                    .orElseThrow(() -> notFound(entry.oldScheduleKey()));
            DayPlan newPlan = planRepo.findByKeyForUpdate(entry.newScheduleKey())
                    .orElseThrow(() -> notFound(entry.newScheduleKey()));
            if (oldPlan.status() != PlanStatus.PUBLISHED) {
                throw conflict("PLAN_STATE_CONFLICT",
                        "仅已发布计划可改签，旧计划 " + entry.oldScheduleKey()
                                + " 当前状态: " + oldPlan.status());
            }
            if (newPlan.status() != PlanStatus.DRAFT) {
                throw conflict("PLAN_STATE_CONFLICT",
                        "改签新计划必须为草稿，" + entry.newScheduleKey()
                                + " 当前状态: " + newPlan.status());
            }
            if (entry.expectedOldVersion() != oldPlan.version()) {
                throw conflict("VERSION_CONFLICT",
                        "expectedOldVersion=" + entry.expectedOldVersion()
                                + " 与旧计划 " + entry.oldScheduleKey() + " 当前版本 "
                                + oldPlan.version() + " 不一致");
            }
            if (entry.expectedNewVersion() != newPlan.version()) {
                throw conflict("VERSION_CONFLICT",
                        "expectedNewVersion=" + entry.expectedNewVersion()
                                + " 与新计划 " + entry.newScheduleKey() + " 当前版本 "
                                + newPlan.version() + " 不一致");
            }
            if (!oldPlan.opDate().equals(newPlan.opDate())) {
                throw conflict("OP_DATE_MISMATCH",
                        "新旧计划运营日必须相同: " + entry.oldScheduleKey() + " 旧=" + oldPlan.opDate()
                                + " " + entry.newScheduleKey() + " 新=" + newPlan.opDate());
            }
            if (planRepo.findLinkByPredecessor(oldPlan.id()).isPresent()) {
                throw conflict("LINK_CONFLICT",
                        "旧计划已存在直接后继: " + entry.oldScheduleKey());
            }
            if (planRepo.findLinkBySuccessor(newPlan.id()).isPresent()) {
                throw conflict("LINK_CONFLICT",
                        "新计划已存在直接前驱: " + entry.newScheduleKey());
            }
            oldPlans.add(oldPlan);
            locked.add(new LockedPlan(newPlan, planRepo.findOccupancies(newPlan.id())));
        }
        List<DayPlan> allPlans = new ArrayList<>(oldPlans);
        locked.forEach(l -> allPlans.add(l.plan()));
        requireSameOpDate(allPlans);

        List<Long> excludeIds = allPlans.stream().map(DayPlan::id).toList();
        SpeedShiftEngine.ShiftOutput output = evaluateShift(locked, excludeIds);
        if (!output.problems().isEmpty()) {
            throw slotConflict(output.problems(), "新草稿存在时隙冲突或无法在运营日内完成顺延，改签未生效");
        }

        long now = clock.nowMillis();
        List<RescheduleResponse> pairs = new ArrayList<>();
        List<Long> newDelays = new ArrayList<>();
        for (int i = 0; i < entries.size(); i++) {
            RescheduleEntry entry = entries.get(i);
            LockedPlan lp = locked.get(i);
            SpeedShiftEngine.UnitResult result = output.results().get(i);
            applyShiftIfNeeded(lp, result.shifted(), result.delayMinutes(), now);
            planRepo.updateStatus(oldPlans.get(i).id(), PlanStatus.CANCELLED, now);
            planRepo.updateStatus(lp.plan().id(), PlanStatus.PUBLISHED, now);
            planRepo.insertRescheduleLink(oldPlans.get(i).id(), lp.plan().id(), now);
            newDelays.add(result.delayMinutes());
            pairs.add(new RescheduleResponse(loadPlan(entry.oldScheduleKey()),
                    loadPlan(entry.newScheduleKey())));
        }
        String recordKey = persistRescheduleRecord(triggerOp, locked, output, speedVersion,
                operator, now);
        return new RescheduleOutcome(pairs, newDelays, speedVersion, output.maxDelayMinutes(),
                recordKey);
    }

    /**
     * 锁内组装引擎输入并执行顺延评估。
     */
    private SpeedShiftEngine.ShiftOutput evaluateShift(List<LockedPlan> locked,
                                                       List<Long> excludePlanIds) {
        LocalDate opDate = locked.get(0).plan().opDate();
        Instant dayStart = opDate.atStartOfDay(OPERATION_ZONE).toInstant();
        Instant dayEnd = opDate.plusDays(1).atStartOfDay(OPERATION_ZONE).toInstant();

        Set<String> sectionIds = new TreeSet<>();
        List<SpeedShiftEngine.ShiftUnit> units = new ArrayList<>();
        for (int i = 0; i < locked.size(); i++) {
            LockedPlan lp = locked.get(i);
            List<Occupancy> occupancies = lp.occupancies().stream()
                    .sorted(java.util.Comparator.comparingInt(Occupancy::seq))
                    .toList();
            occupancies.forEach(o -> sectionIds.add(o.sectionId()));
            units.add(new SpeedShiftEngine.ShiftUnit(i, lp.plan().scheduleKey(), occupancies));
        }
        List<PublishedSlot> externalSlots = planRepo.findPublishedSlots(opDate,
                new ArrayList<>(sectionIds), excludePlanIds);
        SpeedShiftEngine.ShiftInput input = new SpeedShiftEngine.ShiftInput(
                units,
                restrictionService.loadActiveRestrictions(new ArrayList<>(sectionIds)),
                restrictionService.loadSectionLengths(),
                clock.now(), dayStart, dayEnd, properties.headwayMinutes(), externalSlots);
        return SpeedShiftEngine.evaluate(input);
    }

    /**
     * 顺延量为正时以平移后的占用整体替换原占用（版本号不变，原时刻由重排明细固化）。
     */
    private void applyShiftIfNeeded(LockedPlan lp, List<Occupancy> shifted, long delayMinutes,
                                    long nowMillis) {
        if (delayMinutes <= 0L) {
            return;
        }
        planRepo.replaceOccupancies(lp.plan().id(), shifted);
    }

    /**
     * 批内存在正顺延量时固化重排主记录与逐段明细；否则不产生记录，返回 null。
     */
    private String persistRescheduleRecord(String triggerOp, List<LockedPlan> locked,
                                           SpeedShiftEngine.ShiftOutput output, long speedVersion,
                                           String operator, long nowMillis) {
        if (output.maxDelayMinutes() <= 0L) {
            return null;
        }
        // 单计划操作复用其幂等键不适用此处：记录键由触发操作与批内计划集合派生，天然唯一且可复现。
        String recordKey = triggerOp + ":BATCH:" + locked.stream()
                .map(l -> l.plan().scheduleKey())
                .collect(Collectors.joining("|"));
        long recordId = recordRepo.insertRecord(recordKey, triggerOp, recordKey, speedVersion,
                operator, output.maxDelayMinutes(), locked.size(), nowMillis);
        List<RescheduleItem> items = new ArrayList<>();
        for (SpeedShiftEngine.UnitResult result : output.results()) {
            LockedPlan lp = locked.get(result == output.results().get(0) ? 0 : indexOfResult(output, result));
            for (SpeedShiftEngine.SectionEval eval : result.evals()) {
                Occupancy origin = lp.occupancies().stream()
                        .filter(o -> o.seq() == eval.sectionSeq())
                        .findFirst()
                        .orElseThrow(() -> new IllegalStateException("顺延明细缺少原占用: seq="
                                + eval.sectionSeq()));
                items.add(new RescheduleItem(0L, recordId, result == output.results().get(0)
                        && output.results().size() > 1 ? -1 : planSeqOf(output, result),
                        lp.plan().scheduleKey(), eval.sectionSeq(), origin.trainNo(),
                        origin.sectionId(), origin.startUtc(), origin.endUtc(),
                        origin.startUtc().plusMillis(eval.delayMinutes() * 60_000L),
                        origin.endUtc().plusMillis(eval.delayMinutes() * 60_000L),
                        eval.delayMinutes(), eval.actualMinutes(), eval.affectedMinutes(),
                        eval.requiredMinutes(), eval.hitOrderKey(), eval.hitOrderVersion()));
            }
        }
        recordRepo.insertItems(items);
        return recordKey;
    }

    private int indexOfResult(SpeedShiftEngine.ShiftOutput output,
                              SpeedShiftEngine.UnitResult result) {
        for (int i = 0; i < output.results().size(); i++) {
            if (output.results().get(i) == result) {
                return i;
            }
        }
        throw new IllegalStateException("顺延结果缺失: " + result.scheduleKey());
    }

    private int planSeqOf(SpeedShiftEngine.ShiftOutput output, SpeedShiftEngine.UnitResult result) {
        return indexOfResult(output, result);
    }

    // ---------- 校验与映射 ----------

    private record LockedPlan(DayPlan plan, List<Occupancy> occupancies) {
    }

    private void requireSameOpDate(List<DayPlan> plans) {
        LocalDate first = plans.get(0).opDate();
        for (DayPlan p : plans) {
            if (!p.opDate().equals(first)) {
                throw conflict("OP_DATE_MISMATCH",
                        "同批计划运营日必须相同: " + p.scheduleKey() + " 为 " + p.opDate()
                                + "，首批日期为 " + first);
            }
        }
    }

    private void validateDistinctKeys(List<String> keys) {
        Set<String> seen = new HashSet<>();
        for (String key : keys) {
            if (!seen.add(key)) {
                throw badRequest("同批计划不可重复: " + key);
            }
        }
    }

    private void validateRescheduleItems(List<RescheduleBatchRequest.BatchRescheduleItem> items) {
        Set<String> oldKeys = new HashSet<>();
        Set<String> newKeys = new HashSet<>();
        for (RescheduleBatchRequest.BatchRescheduleItem item : items) {
            if (item.oldScheduleKey().equals(item.newScheduleKey())) {
                throw badRequest("新旧计划必须不同: " + item.oldScheduleKey());
            }
            if (!oldKeys.add(item.oldScheduleKey())) {
                throw badRequest("同批旧计划不可重复: " + item.oldScheduleKey());
            }
            if (!newKeys.add(item.newScheduleKey())) {
                throw badRequest("同批新计划不可重复: " + item.newScheduleKey());
            }
        }
    }

    private ApiException slotConflict(List<Map<String, Object>> details, String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "SLOT_CONFLICT", message, details);
    }

    private RescheduleRecordView toRecordView(RescheduleRecord r) {
        return new RescheduleRecordView(r.recordKey(), r.triggerOp(), r.requestKey(),
                r.speedVersion(), r.operator(), r.delayMinutes(), r.planCount(),
                Instant.ofEpochMilli(r.createdAt()));
    }

    private RescheduleItemView toItemView(RescheduleItem i) {
        return new RescheduleItemView(i.planSeq(), i.scheduleKey(), i.sectionSeq(), i.trainNo(),
                i.sectionId(), i.oldStartUtc(), i.oldEndUtc(), i.newStartUtc(), i.newEndUtc(),
                i.delayMinutes(), i.actualMinutes(), i.affectedMinutes(), i.requiredMinutes(),
                i.hitOrderKey(), i.hitOrderVersion());
    }

    private PlanResponse loadPlan(String scheduleKey) {
        DayPlan plan = planRepo.findByKey(scheduleKey)
                .orElseThrow(() -> notFound(scheduleKey));
        List<OccupancyView> views = planRepo.findOccupancies(plan.id()).stream()
                .map(o -> new OccupancyView(o.trainNo(), o.sectionId(), o.startUtc(), o.endUtc()))
                .toList();
        return new PlanResponse(plan.scheduleKey(), plan.opDate(), plan.version(),
                plan.status().name(), views);
    }

    private List<Occupancy> toOccupancies(long planId, List<OccupancyRequest> requests) {
        List<Occupancy> result = new ArrayList<>(requests.size());
        for (int i = 0; i < requests.size(); i++) {
            OccupancyRequest r = requests.get(i);
            result.add(new Occupancy(0L, planId, i, r.trainNo(), r.sectionId(), r.startUtc(), r.endUtc()));
        }
        return result;
    }

    /**
     * 参数级校验：结束必须晚于开始，且起止落在同一 Asia/Shanghai 日历日内。
     */
    private void validateOccupancyParams(List<OccupancyRequest> occupancies) {
        for (int i = 0; i < occupancies.size(); i++) {
            OccupancyRequest o = occupancies.get(i);
            if (!o.endUtc().isAfter(o.startUtc())) {
                throw badRequest("第 " + i + " 条占用结束时刻必须晚于开始时刻");
            }
            LocalDate startDay = o.startUtc().atZone(OPERATION_ZONE).toLocalDate();
            LocalDate endDay = o.endUtc().minusNanos(1).atZone(OPERATION_ZONE).toLocalDate();
            if (!startDay.equals(endDay)) {
                throw badRequest("第 " + i + " 条占用必须落在同一运营日（Asia/Shanghai）内");
            }
        }
    }

    /**
     * 占用必须落在计划运营日内：[start, end) 完全包含于运营日 [dayStart, dayEnd)。
     */
    private void validateWithinOperationDay(List<OccupancyRequest> occupancies, LocalDate opDate) {
        Instant dayStart = opDate.atStartOfDay(OPERATION_ZONE).toInstant();
        Instant dayEnd = opDate.plusDays(1).atStartOfDay(OPERATION_ZONE).toInstant();
        for (int i = 0; i < occupancies.size(); i++) {
            OccupancyRequest o = occupancies.get(i);
            if (o.startUtc().isBefore(dayStart) || o.endUtc().isAfter(dayEnd)) {
                throw badRequest("第 " + i + " 条占用不在运营日 " + opDate + "（Asia/Shanghai）内");
            }
        }
    }

    /**
     * 幂等重放：存在记录且参数一致返回首次结果；参数不一致抛 409。
     */
    private Optional<PlanResponse> replayIfPresent(String opType, String requestKey, String hash) {
        return replayIfPresent(opType, requestKey, hash, PlanResponse.class);
    }

    /**
     * 幂等重放（泛型）：存在记录且参数一致返回首次结果；参数不一致抛 409。
     */
    private <T> Optional<T> replayIfPresent(String opType, String requestKey, String hash,
                                            Class<T> type) {
        return idemRepo.find(opType, requestKey).map(record -> {
            if (!record.requestHash().equals(hash)) {
                throw conflict("IDEMPOTENT_KEY_REUSED",
                        "requestKey 已用于其他参数: " + requestKey);
            }
            return fromJson(record.responseJson(), type);
        });
    }

    /**
     * 并发下唯一键冲突后的裁决：若为同键重放返回首次结果，否则说明 scheduleKey 冲突。
     */
    private PlanResponse resolveDuplicate(String opType, String requestKey, String hash) {
        return replayIfPresent(opType, requestKey, hash)
                .orElseThrow(() -> conflict("SCHEDULE_KEY_EXISTS", "scheduleKey 已存在"));
    }

    private String hashCreate(CreatePlanRequest req) {
        StringBuilder sb = new StringBuilder(OP_CREATE).append('\n')
                .append(req.scheduleKey()).append('\n').append(req.opDate());
        appendOccupancies(sb, req.occupancies());
        return sha256(sb.toString());
    }

    private String hashUpdate(String scheduleKey, UpdateOccupanciesRequest req) {
        StringBuilder sb = new StringBuilder(OP_UPDATE).append('\n')
                .append(scheduleKey).append('\n').append(req.expectedVersion());
        appendOccupancies(sb, req.occupancies());
        return sha256(sb.toString());
    }

    private String hashAction(String opType, String scheduleKey) {
        return sha256(opType + '\n' + scheduleKey);
    }

    private String hashReschedule(String oldScheduleKey, RescheduleRequest req) {
        return sha256(OP_RESCHEDULE + '\n' + oldScheduleKey + '\n' + req.newScheduleKey()
                + '\n' + req.expectedOldVersion() + '\n' + req.expectedNewVersion());
    }

    private String hashKeyList(String opType, List<String> keys, String operator) {
        return sha256(opType + '\n' + String.join("|", keys) + '\n' + operator);
    }

    private String hashRescheduleBatch(String opType,
                                       List<RescheduleBatchRequest.BatchRescheduleItem> items,
                                       String operator) {
        StringBuilder sb = new StringBuilder(opType).append('\n').append(operator);
        for (RescheduleBatchRequest.BatchRescheduleItem item : items) {
            sb.append('\n').append(item.oldScheduleKey()).append('>')
                    .append(item.newScheduleKey()).append('@')
                    .append(item.expectedOldVersion()).append(':')
                    .append(item.expectedNewVersion());
        }
        return sha256(sb.toString());
    }

    private void appendOccupancies(StringBuilder sb, List<OccupancyRequest> occupancies) {
        for (OccupancyRequest o : occupancies) {
            sb.append('\n').append(o.trainNo()).append('|').append(o.sectionId()).append('|')
                    .append(o.startUtc().toEpochMilli()).append('|').append(o.endUtc().toEpochMilli());
        }
    }

    private String normalizeOperator(String operator) {
        return operator == null || operator.isBlank()
                ? RestrictionService.SYSTEM_OPERATOR
                : operator.trim();
    }

    private String sha256(String text) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashed = digest.digest(text.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(hashed.length * 2);
            for (byte b : hashed) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
                hex.append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }

    private String toJson(Object response) {
        try {
            return objectMapper.writeValueAsString(response);
        } catch (Exception e) {
            throw new IllegalStateException("响应序列化失败", e);
        }
    }

    private <T> T fromJson(String json, Class<T> type) {
        try {
            return objectMapper.readValue(json, type);
        } catch (Exception e) {
            throw new IllegalStateException("幂等响应反序列化失败", e);
        }
    }

    private ApiException badRequest(String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, "INVALID_ARGUMENT", message);
    }

    private ApiException notFound(String scheduleKey) {
        return new ApiException(HttpStatus.NOT_FOUND, "PLAN_NOT_FOUND",
                "计划不存在: " + scheduleKey);
    }

    private ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }
}

