/**
 * 线路区段与气象限速令 API：区段登记、限速令登记/修订/撤销、
 * 生效限速查询、版本明细与只读诊断。
 */
@RestController
@RequestMapping("/api/v1")
public class RestrictionController {

    private final RestrictionService service;

    public RestrictionController(RestrictionService service) {
        this.service = service;
    }

    /**
     * 登记既有线路区段。
     */
    @PostMapping("/sections")
    @ResponseStatus(HttpStatus.CREATED)
    public SectionView registerSection(@Valid @RequestBody RegisterSectionRequest request) {
        return service.registerSection(request);
    }

    /**
     * 列出全部区段。
     */
    @GetMapping("/sections")
    public List<SectionView> listSections() {
        return service.getSections();
    }

    /**
     * 登记气象限速令版本 1。速度 10～300，区段或时段非法返回 422。
     */
    @PostMapping("/restrictions")
    @ResponseStatus(HttpStatus.CREATED)
    public RestrictionVersionView register(@Valid @RequestBody RestrictionRegisterRequest request) {
        return service.register(request);
    }

    /**
     * 修订限速令，追加 ACTIVE 新版本。
     */
    @PostMapping("/restrictions/{orderKey}/revise")
    public RestrictionVersionView revise(@PathVariable String orderKey,
                                         @Valid @RequestBody RestrictionReviseRequest request) {
        return service.revise(orderKey, request);
    }

    /**
     * 撤销限速令，追加 REVOKED 版本；历史版本与已固化重排记录均不变。
     */
    @PostMapping("/restrictions/{orderKey}/revoke")
    public RestrictionVersionView revoke(@PathVariable String orderKey,
                                         @Valid @RequestBody RestrictionRevokeRequest request) {
        return service.revoke(orderKey, request);
    }

    /**
     * 查询限速令全部不可变版本（版本明细/历史）。
     */
    @GetMapping("/restrictions/{orderKey}")
    public List<RestrictionVersionView> getOrder(@PathVariable String orderKey) {
        return service.getOrderDetail(orderKey);
    }

    /**
     * 查询当前生效限速；sectionId 可空，空则返回全部区段。
     */
    @GetMapping("/restrictions/active")
    public List<ActiveRestrictionView> getActive(
            @RequestParam(name = "sectionId", required = false) String sectionId) {
        return service.getActiveRestrictions(sectionId);
    }

    /**
     * 只读诊断：限速全局版本、最小间隔、生效限速、区段与当前时刻。
     */
    @GetMapping("/diagnostics")
    public DiagnosticResponse diagnostics() {
        return service.getDiagnostics();
    }
}

