 */
public BatchRescheduleResponse rescheduleBatch(RescheduleBatchRequest req) {
    String operator = normalizeOperator(req.operator());
    List<RescheduleBatchRequest.BatchRescheduleItem> items = req.items();
    validateRescheduleItems(items);
    List<String> oldKeys = items.stream().map(RescheduleBatchRequest.BatchRescheduleItem::oldScheduleKey).toList();
    List<String> newKeys = items.stream().map(RescheduleBatchRequest.BatchRescheduleItem::newScheduleKey).toList();
    String hash = hashRescheduleBatch(OP_RESCHEDULE_BATCH, items, operator);
    Optional<BatchRescheduleResponse> replay =
            replayIfPresent(OP_RESCHEDULE_BATCH, req.requestKey(), hash,
                    BatchRescheduleResponse.class);
    if (replay.isPresent()) {
        return replay.get();
    }
    return tx.execute(status -> {
        List<RescheduleEntry> entries = items.stream()
                .map(i -> new RescheduleEntry(i.oldScheduleKey(), i.newScheduleKey(),
                        i.expectedOldVersion(), i.expectedNewVersion()))
                .toList();
        RescheduleOutcome outcome = executeReschedule(entries, operator,
                OP_RESCHEDULE_BATCH, req.requestKey());
        BatchRescheduleResponse response = new BatchRescheduleResponse(outcome.speedVersion(),
                operator, outcome.maxDelayMinutes(), properties.headwayMinutes(),
                outcome.pairs(), outcome.newDelays(), outcome.recordKey(), clock.now());
        idemRepo.insert(OP_RESCHEDULE_BATCH, req.requestKey(), hash, toJson(response),
                clock.nowMillis());
        return response;
