public RestrictionVersionView revoke(String orderKey, RestrictionRevokeRequest req) {
    String operator = normalizeOperator(req.operator());
    String hash = sha256(OP_RESTRICTION_REVOKE + '\n' + orderKey + '\n' + operator);
    Optional<RestrictionVersionView> replay =
            replay(OP_RESTRICTION_REVOKE, req.requestKey(), hash, RestrictionVersionView.class);
    if (replay.isPresent()) {
        return replay.get();
    }
    return tx.execute(status -> {
        planRepo.acquirePublishLock();
        SpeedOrderVersion latest = speedRepo.findLatestVersion(orderKey)
                .orElseThrow(() -> orderNotFound(orderKey));
        if (latest.status() != SpeedOrderStatus.ACTIVE) {
            throw conflict("RESTRICTION_NOT_ACTIVE",
                    "限速令已撤销，不可重复撤销: " + orderKey);
        }
        long now = clock.nowMillis();
        int newVersion = latest.version() + 1;
        long globalVersion = speedRepo.currentVersionForUpdate() + 1;
        speedRepo.insertVersion(orderKey, newVersion, latest.sectionId(), null, null, null,
                SpeedOrderStatus.REVOKED, operator, globalVersion, now);
        speedRepo.updateGlobalVersion(globalVersion);
        RestrictionVersionView view = toView(orderKey, newVersion, latest.sectionId(), null,
                null, null, SpeedOrderStatus.REVOKED, operator, now, globalVersion);
        idemRepo.insert(OP_RESTRICTION_REVOKE, req.requestKey(), hash, toJson(view), now);
        return view;
    });
}

