package com.example.starter.plan.service;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.starter.plan.model.ActiveRestriction;
import com.example.starter.plan.model.Occupancy;
import com.example.starter.plan.model.PublishedSlot;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.List;
import java.util.Map;
import org.junit.jupiter.api.Test;

/**
 * 气象限速顺延引擎纯计算单元测试：顺延量、最小间隔取整、多令取最低速、
 * 批内传递与再判定、已开始/越运营日/外部与批内冲突、受影响分钟与证据字段。
 */
class SpeedShiftEngineTest {

    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);
    private static final Instant DAY_START = DAY.atStartOfDay(SH).toInstant();
    private static final Instant DAY_END = DAY.plusDays(1).atStartOfDay(SH).toInstant();
    private static final long HEADWAY = 5L;

    /** 无任何限速：不顺延、无问题。 */
    @Test
    void noRestrictionMeansNoDelay() {
        SpeedShiftEngine.ShiftOutput out = SpeedShiftEngine.evaluate(input(
                List.of(unit(0, "P0", occ(0, "G1", "S1", 8, 0, 9, 0))),
                List.of(), at(7, 0)));
        assertThat(out.problems()).isEmpty();
        assertThat(out.results().get(0).delayMinutes()).isZero();
        assertThat(out.maxDelayMinutes()).isZero();
    }

    /** 60 公里区段限速 60 km/h、原排 40 分钟违反限速：平移至窗口结束 10:00，顺延 120 分钟。 */
    @Test
    void violatingRunShiftsUntilWindowEnd() {
        Occupancy o = occ(0, "G1", "S1", 8, 0, 8, 40);
        SpeedShiftEngine.ShiftOutput out = SpeedShiftEngine.evaluate(input(
                List.of(unit(0, "P0", o)),
                List.of(restriction("W1", 1, "S1", 8, 0, 10, 0, 60)), at(7, 0)));

        assertThat(out.problems()).isEmpty();
        SpeedShiftEngine.UnitResult r = out.results().get(0);
        assertThat(r.delayMinutes()).isEqualTo(120L);
        assertThat(r.shifted().get(0).startUtc()).isEqualTo(t(10, 0));
        assertThat(r.shifted().get(0).endUtc()).isEqualTo(t(10, 40));
        SpeedShiftEngine.SectionEval eval = r.evals().get(0);
        assertThat(eval.actualMinutes()).isEqualTo(40L);
        assertThat(eval.requiredMinutes()).isEqualTo(60L);
        assertThat(eval.affectedMinutes()).isEqualTo(40L);
        assertThat(eval.hitOrderKey()).isEqualTo("W1");
        assertThat(eval.hitOrderVersion()).isEqualTo(1);
    }

