    // ---------- 辅助 ----------

    private static Instant t(int hour, int minute) {
        return DAY.atTime(hour, minute).atZone(SH).toInstant();
    }

    private static Instant at(int hour, int minute) {
        return t(hour, minute);
    }

    private static Occupancy occ(int seq, String train, String section, int sh, int sm,
                                 int eh, int em) {
        return new Occupancy(seq + 1L, seq + 100L, seq, train, section, t(sh, sm), t(eh, em));
    }

    private static SpeedShiftEngine.ShiftUnit unit(int planSeq, String key, Occupancy... occs) {
        return new SpeedShiftEngine.ShiftUnit(planSeq, key, List.of(occs));
    }

    private static ActiveRestriction restriction(String key, int version, String section,
                                                 int sh, int sm, int eh, int em, int speed) {
        return new ActiveRestriction(key, version, section, t(sh, sm), t(eh, em), speed, "DISPATCH");
    }

    private static SpeedShiftEngine.ShiftInput input(
            List<SpeedShiftEngine.ShiftUnit> units, List<ActiveRestriction> restrictions,
            Instant now) {
        return new SpeedShiftEngine.ShiftInput(units, restrictions,
                Map.of("S1", 60_000L, "S2", 60_000L), now, DAY_START, DAY_END, HEADWAY, List.of());
    }
}

