package com.example.starter.plan;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.example.starter.plan.service.RailClock;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.UUID;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

/**
 * 区段登记与气象限速令端到端测试（H2 内存库）：登记/修订/撤销、422 非法输入、
 * 409 状态与幂等冲突、版本不可变、多令叠加与只读诊断。
 */
@SpringBootTest
@AutoConfigureMockMvc
class RestrictionApiTest {

    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);

    @Autowired
    private MockMvc mvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private RailClock clock;

    private Instant pinnedNow;

    @BeforeEach
    void pinClock() {
        pinnedNow = DAY.atTime(7, 0).atZone(SH).toInstant();
        clock.pinTo(pinnedNow);
    }

    @AfterEach
    void resetClock() {
        clock.reset();
    }

    @Test
    void registerSectionReplayAndConflict() throws Exception {
        String sectionId = key("SEC");
        String body = sectionBody(key("REQ"), sectionId, "测试区段", 60_000);
        MvcResult first = mvc.perform(post("/api/v1/sections")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated()).andReturn();
        assertThat(read(first).get("lengthMeters").asLong()).isEqualTo(60_000L);

        // 同键同参重放
        MvcResult replay = mvc.perform(post("/api/v1/sections")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated()).andReturn();
        assertThat(read(replay)).isEqualTo(read(first));

        // 同键异参 409
        mvc.perform(post("/api/v1/sections").contentType(MediaType.APPLICATION_JSON)
                        .content(sectionBody(key2("REQ"), sectionId, "测试区段", 60_000)))
                .andExpect(status().isConflict());
    }

    @Test
    void registerReviseRevokeKeepsImmutableVersions() throws Exception {
        String section = registerSection(60_000);
        String orderKey = key("ORD");

        // 登记版本 1，全局版本至少为 1
        MvcResult registered = mvc.perform(post("/api/v1/restrictions")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), orderKey, section,
                                iso(8), iso(10), 60, "DISP-A")))
                .andExpect(status().isCreated()).andReturn();
        JsonNode v1 = read(registered);
        assertThat(v1.get("version").asInt()).isEqualTo(1);
        assertThat(v1.get("status").asText()).isEqualTo("ACTIVE");
        assertThat(v1.get("maxSpeedKmh").asInt()).isEqualTo(60);
        assertThat(v1.get("operator").asText()).isEqualTo("DISP-A");
        long gv1 = v1.get("globalVersion").asLong();
        assertThat(gv1).isGreaterThanOrEqualTo(1);

        // 修订版本 2，全局版本推进
        MvcResult revised = mvc.perform(post("/api/v1/restrictions/{key}/revise", orderKey)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reviseBody(key("REQ"), iso(9), iso(11), 45, "DISP-B")))
                .andExpect(status().isOk()).andReturn();
        JsonNode v2 = read(revised);
        assertThat(v2.get("version").asInt()).isEqualTo(2);
        assertThat(v2.get("maxSpeedKmh").asInt()).isEqualTo(45);
        assertThat(v2.get("globalVersion").asLong()).isEqualTo(gv1 + 1);

        // 撤销版本 3（REVOKED 行窗口与速度为 null）
        MvcResult revoked = mvc.perform(post("/api/v1/restrictions/{key}/revoke", orderKey)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(revokeBody(key("REQ"), "DISP-C")))
                .andExpect(status().isOk()).andReturn();
        JsonNode v3 = read(revoked);
        assertThat(v3.get("version").asInt()).isEqualTo(3);
        assertThat(v3.get("status").asText()).isEqualTo("REVOKED");
        assertThat(v3.get("startUtc").isNull()).isTrue();
        assertThat(v3.get("endUtc").isNull()).isTrue();
        assertThat(v3.get("maxSpeedKmh").isNull()).isTrue();
        assertThat(v3.get("globalVersion").asLong()).isEqualTo(gv1 + 2);

        // 历史明细三行齐全，v1/v2 字段不被后续撤销改写
        MvcResult detail = mvc.perform(get("/api/v1/restrictions/{key}", orderKey))
                .andExpect(status().isOk()).andReturn();
        JsonNode versions = read(detail);
        assertThat(versions).hasSize(3);
        assertThat(versions.get(0).get("version").asInt()).isEqualTo(1);
        assertThat(versions.get(0).get("maxSpeedKmh").asInt()).isEqualTo(60);
        assertThat(versions.get(0).get("globalVersion").asLong()).isEqualTo(gv1);
        assertThat(versions.get(1).get("maxSpeedKmh").asInt()).isEqualTo(45);
        assertThat(versions.get(2).get("status").asText()).isEqualTo("REVOKED");

        // 已撤销不可再撤销/修订
        mvc.perform(post("/api/v1/restrictions/{key}/revoke", orderKey)
                        .contentType(MediaType.APPLICATION_JSON).content(revokeBody(key("REQ"))))
                .andExpect(status().isConflict());
        mvc.perform(post("/api/v1/restrictions/{key}/revise", orderKey)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reviseBody(key("REQ"), iso(9), iso(11), 40)))
                .andExpect(status().isConflict());

        // 生效列表不再含该令
        MvcResult active = mvc.perform(get("/api/v1/restrictions/active")
                        .param("sectionId", section))
                .andExpect(status().isOk()).andReturn();
        assertThat(read(active).toString()).doesNotContain(orderKey);
    }

    @Test
    void invalidSpeedWindowAndSectionReturn422() throws Exception {
        String section = registerSection(60_000);

        // 速度下边界 9、上边界 301、缺失
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), section, iso(8), iso(10), 9)))
                .andExpect(status().isUnprocessableEntity());
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), section, iso(8), iso(10), 301)))
                .andExpect(status().isUnprocessableEntity());
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestKey\":\"" + key("REQ") + "\",\"orderKey\":\"" + key("ORD")
                                + "\",\"sectionId\":\"" + section + "\",\"startUtc\":\"" + iso(8)
                                + "\",\"endUtc\":\"" + iso(10) + "\"}"))
                .andExpect(status().isUnprocessableEntity());
        // 窗口结束早于/等于开始、窗口缺失
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), section, iso(10), iso(8), 60)))
                .andExpect(status().isUnprocessableEntity());
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), section, iso(8), iso(8), 60)))
                .andExpect(status().isUnprocessableEntity());
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestKey\":\"" + key("REQ") + "\",\"orderKey\":\"" + key("ORD")
                                + "\",\"sectionId\":\"" + section + "\",\"maxSpeedKmh\":60}"))
                .andExpect(status().isUnprocessableEntity());
        // 未知区段
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), key("NO-SEC"),
                                iso(8), iso(10), 60)))
                .andExpect(status().isUnprocessableEntity());
        // 边界值 10 与 300 合法
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), section, iso(8), iso(9), 10)))
                .andExpect(status().isCreated());
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), section, iso(8), iso(9), 300)))
                .andExpect(status().isCreated());
    }

    @Test
    void duplicateOrderKeyReplayDifferentParamsAndFailureNotConsumingKey() throws Exception {
        String section = registerSection(60_000);
        String orderKey = key("ORD");
        String requestKey = key("REQ");

        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(requestKey, orderKey, section, iso(8), iso(10), 60)))
                .andExpect(status().isCreated());
        // 令键重复 409
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), orderKey, section, iso(8), iso(10), 60)))
                .andExpect(status().isConflict());

        // 修订同键同参重放首次结果
        String reviseBody = reviseBody(requestKey, iso(9), iso(11), 50);
        MvcResult first = mvc.perform(post("/api/v1/restrictions/{key}/revise", orderKey)
                        .contentType(MediaType.APPLICATION_JSON).content(reviseBody))
                .andExpect(status().isOk()).andReturn();
        MvcResult replay = mvc.perform(post("/api/v1/restrictions/{key}/revise", orderKey)
                        .contentType(MediaType.APPLICATION_JSON).content(reviseBody))
                .andExpect(status().isOk()).andReturn();
        assertThat(read(replay)).isEqualTo(read(first));

        // 同键异参 409
        mvc.perform(post("/api/v1/restrictions/{key}/revise", orderKey)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reviseBody(requestKey, iso(9), iso(11), 40)))
                .andExpect(status().isConflict());

        // 失败不占键：非法速度 422 后同键合法参数成功
        String retryKey = key("REQ");
        mvc.perform(post("/api/v1/restrictions/{key}/revise", orderKey)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reviseBody(retryKey, iso(9), iso(11), 999)))
                .andExpect(status().isUnprocessableEntity());
        mvc.perform(post("/api/v1/restrictions/{key}/revise", orderKey)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(reviseBody(retryKey, iso(9), iso(11), 55)))
                .andExpect(status().isOk());
    }

    @Test
    void multipleActiveOrdersCoexistAndDiagnosticsIsReadOnly() throws Exception {
        String section = registerSection(60_000);
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), section, iso(8), iso(10), 60)))
                .andExpect(status().isCreated());
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content(registerBody(key("REQ"), key("ORD"), section, iso(8), iso(10), 45)))
                .andExpect(status().isCreated());

        MvcResult active = mvc.perform(get("/api/v1/restrictions/active")
                        .param("sectionId", section))
                .andExpect(status().isOk()).andReturn();
        JsonNode rows = read(active);
        assertThat(rows).hasSize(2);

        // 诊断只读：连续两次结果一致（固定时钟下 now 亦一致）
        MvcResult d1 = mvc.perform(get("/api/v1/diagnostics")).andExpect(status().isOk()).andReturn();
        MvcResult d2 = mvc.perform(get("/api/v1/diagnostics")).andExpect(status().isOk()).andReturn();
        JsonNode diag1 = read(d1);
        JsonNode diag2 = read(d2);
        assertThat(diag2).isEqualTo(diag1);
        assertThat(diag1.get("headwayMinutes").asLong()).isEqualTo(5L);
        assertThat(diag1.get("nowUtc").asText()).isEqualTo(pinnedNow.toString());
        assertThat(diag1.get("activeRestrictions").toString()).contains(section);
    }

    @Test
    void missingOrderReturns404() throws Exception {
        mvc.perform(get("/api/v1/restrictions/{key}", key("ORD")))
                .andExpect(status().isNotFound());
    }

    // ---------- 辅助 ----------

    private String registerSection(long lengthMeters) throws Exception {
        String section = key("SEC");
        mvc.perform(post("/api/v1/sections").contentType(MediaType.APPLICATION_JSON)
                        .content(sectionBody(key("REQ"), section, "测试区段", lengthMeters)))
                .andExpect(status().isCreated());
        return section;
    }

    private JsonNode read(MvcResult result) throws Exception {
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private static String key(String prefix) {
        return prefix + "-" + UUID.randomUUID();
    }

    private static String key2(String prefix) {
        return prefix + "-" + UUID.randomUUID() + "-X";
    }

    private static String iso(int hour) {
        return DAY.atTime(hour, 0).atZone(SH).toInstant().toString();
    }

    private static String sectionBody(String requestKey, String sectionId, String name, long length) {
        return "{\"requestKey\":\"" + requestKey + "\",\"sectionId\":\"" + sectionId
                + "\",\"sectionName\":\"" + name + "\",\"lengthMeters\":" + length + "}";
    }

    private static String registerBody(String requestKey, String orderKey, String sectionId,
                                       String start, String end, int speed) {
        return registerBody(requestKey, orderKey, sectionId, start, end, speed, null);
    }

    private static String registerBody(String requestKey, String orderKey, String sectionId,
                                       String start, String end, int speed, String operator) {
        return "{\"requestKey\":\"" + requestKey + "\",\"orderKey\":\"" + orderKey
                + "\",\"sectionId\":\"" + sectionId + "\",\"startUtc\":\"" + start
                + "\",\"endUtc\":\"" + end + "\",\"maxSpeedKmh\":" + speed
                + (operator == null ? "" : ",\"operator\":\"" + operator + "\"") + "}";
    }

    private static String reviseBody(String requestKey, String start, String end, int speed) {
        return reviseBody(requestKey, start, end, speed, null);
    }

    private static String reviseBody(String requestKey, String start, String end, int speed,
                                     String operator) {
        return "{\"requestKey\":\"" + requestKey + "\",\"startUtc\":\"" + start
                + "\",\"endUtc\":\"" + end + "\",\"maxSpeedKmh\":" + speed
                + (operator == null ? "" : ",\"operator\":\"" + operator + "\"") + "}";
    }

    private static String revokeBody(String requestKey) {
        return revokeBody(requestKey, null);
    }

    private static String revokeBody(String requestKey, String operator) {
        return "{\"requestKey\":\"" + requestKey + "\""
                + (operator == null ? "" : ",\"operator\":\"" + operator + "\"") + "}";
    }
}

