package com.example.starter.plan;

import static org.assertj.core.api.Assertions.assertThat;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.UUID;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;

/**
 * 气象限速重排端到端测试（H2 内存库）：发布/改签整体顺延、逐段分钟数与证据固化、
 * 撤销不改写历史、批量发布传递、顺延后冲突整次 422 且无半成品、已开始不可重排、幂等边界。
 */
@SpringBootTest
@AutoConfigureMockMvc
class WeatherRescheduleApiTest {

    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);

    @Autowired
    private MockMvc mvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private com.example.starter.plan.service.RailClock clock;

    @BeforeEach
    void pinClock() {
        clock.pinTo(DAY.atTime(7, 0).atZone(SH).toInstant());
    }

    @AfterEach
    void resetClock() {
        clock.reset();
    }

    @Test
    void publishShiftsViolatingPlanAndFreezesImmutableEvidence() throws Exception {
        String section = registerSection(60_000);
        String plan = key("SCH");
        createPlan(plan, occ("G1", section, iso(8), iso(8, 40)));
        registerOrder(key("ORD"), section, iso(8), iso(10), 60);

        String publishKey = key("REQ");
        MvcResult published = mvc.perform(post("/api/v1/plans/{key}/publish", plan)
                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(publishKey)))
                .andExpect(status().isOk()).andReturn();
        JsonNode planBody = read(published);
        assertThat(planBody.get("status").asText()).isEqualTo("PUBLISHED");
        assertThat(planBody.get("occupancies").get(0).get("startUtc").asText())
                .isEqualTo(iso(10));
        assertThat(planBody.get("occupancies").get(0).get("endUtc").asText())
                .isEqualTo(iso(10, 40));

        // 生效时隙为顺延后时刻
        JsonNode slots = read(mvc.perform(get("/api/v1/published-slots")
                        .param("date", DAY.toString()).param("sectionId", section))
                .andExpect(status().isOk()).andReturn());
        assertThat(slots).hasSize(1);
        assertThat(slots.get(0).get("startUtc").asText()).isEqualTo(iso(10));

        // 重排历史证据
        JsonNode records = read(mvc.perform(get("/api/v1/plans/{key}/reschedule-records", plan))
                .andExpect(status().isOk()).andReturn());
        assertThat(records).hasSize(1);
        String recordKey = records.get(0).get("recordKey").asText();
        assertThat(recordKey).isEqualTo("PUBLISH:" + publishKey);
        assertThat(records.get(0).get("delayMinutes").asLong()).isEqualTo(120L);
        assertThat(records.get(0).get("planCount").asInt()).isEqualTo(1);
        assertThat(records.get(0).get("speedVersion").asLong()).isGreaterThanOrEqualTo(1);

        JsonNode detail = read(mvc.perform(get("/api/v1/reschedule-records/{key}", recordKey))
                .andExpect(status().isOk()).andReturn());
        assertThat(detail.get("record").get("triggerOp").asText()).isEqualTo("PUBLISH");
        JsonNode items = detail.get("items");
        assertThat(items).hasSize(1);
        JsonNode item = items.get(0);
        assertThat(item.get("planSeq").asInt()).isZero();
        assertThat(item.get("sectionSeq").asInt()).isZero();
        assertThat(item.get("oldStartUtc").asText()).isEqualTo(iso(8));
        assertThat(item.get("oldEndUtc").asText()).isEqualTo(iso(8, 40));
        assertThat(item.get("newStartUtc").asText()).isEqualTo(iso(10));
        assertThat(item.get("newEndUtc").asText()).isEqualTo(iso(10, 40));
        assertThat(item.get("delayMinutes").asLong()).isEqualTo(120L);
        assertThat(item.get("actualMinutes").asLong()).isEqualTo(40L);
        assertThat(item.get("affectedMinutes").asLong()).isEqualTo(40L);
        assertThat(item.get("requiredMinutes").asLong()).isEqualTo(60L);
        assertThat(item.get("hitOrderKey").asText()).startsWith("ORD-");
        assertThat(item.get("hitOrderVersion").asInt()).isEqualTo(1);

        // 撤销限速令：已发布计划与历史证据均不变
        revokeOrder(item.get("hitOrderKey").asText());
        JsonNode detailAfter = read(mvc.perform(get("/api/v1/reschedule-records/{key}", recordKey))
                .andExpect(status().isOk()).andReturn());
        assertThat(detailAfter).isEqualTo(detail);
        JsonNode planAfter = read(mvc.perform(get("/api/v1/plans/{key}", plan))
                .andExpect(status().isOk()).andReturn());
        assertThat(planAfter.get("occupancies").get(0).get("startUtc").asText())
                .isEqualTo(iso(10));
    }

    @Test
    void compliantRunPublishesWithoutShiftAndRecord() throws Exception {
        String section = registerSection(60_000);
        String plan = key("SCH");
        createPlan(plan, occ("G1", section, iso(8), iso(9)));
        registerOrder(key("ORD"), section, iso(8), iso(10), 60);

        mvc.perform(post("/api/v1/plans/{key}/publish", plan)
                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(key("REQ"))))
                .andExpect(status().isOk());
        JsonNode records = read(mvc.perform(get("/api/v1/plans/{key}/reschedule-records", plan))
                .andExpect(status().isOk()).andReturn());
        assertThat(records).isEmpty();
    }

    @Test
    void batchPublishPropagatesDelayAndReturnsActualValues() throws Exception {
        String s1 = registerSection(60_000);
        String s2 = registerSection(60_000);
        String p0 = key("SCH");
        String p1 = key("SCH");
        createPlan(p0, occ("G1", s1, iso(8), iso(8, 40)));
        createPlan(p1, occ("G2", s2, iso(9), iso(10)));
        registerOrder(key("ORD"), s1, iso(8), iso(10), 60);

        String requestKey = key("REQ");
        String body = publishBatchBody(requestKey, "DISP-X", p0, p1);
        MvcResult first = mvc.perform(post("/api/v1/plans/publish-batch")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk()).andReturn();
        JsonNode resp = read(first);
        assertThat(resp.get("maxDelayMinutes").asLong()).isEqualTo(120L);
        assertThat(resp.get("headwayMinutes").asLong()).isEqualTo(5L);
        assertThat(resp.get("delays").get(0).asLong()).isEqualTo(120L);
        assertThat(resp.get("delays").get(1).asLong()).isEqualTo(120L);
        assertThat(resp.get("operator").asText()).isEqualTo("DISP-X");
        assertThat(resp.get("rescheduleRecordKey").asText())
                .isEqualTo("PUBLISH_BATCH:" + requestKey);
        assertThat(resp.get("plans").get(1).get("occupancies").get(0).get("startUtc").asText())
                .isEqualTo(iso(11));

        // 同键同参重放首次完整结果
        MvcResult replay = mvc.perform(post("/api/v1/plans/publish-batch")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk()).andReturn();
        assertThat(read(replay)).isEqualTo(resp);

        // 同键异参（操作者不同）409
        mvc.perform(post("/api/v1/plans/publish-batch")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(publishBatchBody(requestKey, "DISP-Y", p0, p1)))
                .andExpect(status().isConflict());

        // 后续计划证据明细：自身未命中限速，命中令为 null
        JsonNode detail = read(mvc.perform(get("/api/v1/reschedule-records/{key}",
                        resp.get("rescheduleRecordKey").asText()))
                .andExpect(status().isOk()).andReturn());
        JsonNode second = detail.get("items").get(1);
        assertThat(second.get("scheduleKey").asText()).isEqualTo(p1);
        assertThat(second.get("hitOrderKey").isNull()).isTrue();
        assertThat(second.get("hitOrderVersion").isNull()).isTrue();
        assertThat(second.get("delayMinutes").asLong()).isEqualTo(120L);
    }

    @Test
    void batchShiftConflictRollsBackWholeBatchAndFailureDoesNotConsumeKey() throws Exception {
        String section = registerSection(60_000);
        // 第三方已发布占据顺延后的 10:00-11:00
        String thirdParty = key("SCH");
        createPlan(thirdParty, occ("G9", section, iso(10), iso(11)));
        publishPlan(thirdParty, key("REQ"));

        String p0 = key("SCH");
        createPlan(p0, occ("G1", section, iso(8), iso(8, 40)));
        String orderKey = key("ORD");
        registerOrder(orderKey, section, iso(8), iso(10), 60);

        String requestKey = key("REQ");
        MvcResult fail = mvc.perform(post("/api/v1/plans/publish-batch")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(publishBatchBody(requestKey, null, p0)))
                .andExpect(status().isUnprocessableEntity()).andReturn();
        JsonNode error = read(fail);
        assertThat(error.get("code").asText()).isEqualTo("SLOT_CONFLICT");
        JsonNode d = error.get("details").get(0);
        assertThat(d.get("type").asText()).isEqualTo("SECTION_CONFLICT");
        assertThat(d.get("sectionId").asText()).isEqualTo(section);
        assertThat(d.get("scheduleKey").asText()).isEqualTo(p0);
        assertThat(d.get("conflictingScheduleKey").asText()).isEqualTo(thirdParty);
        assertThat(d.get("startUtc").asText()).isEqualTo(iso(10));

        // 整批回滚：计划仍草稿、原占用不变、无重排记录
        JsonNode planBody = read(mvc.perform(get("/api/v1/plans/{key}", p0))
                .andExpect(status().isOk()).andReturn());
        assertThat(planBody.get("status").asText()).isEqualTo("DRAFT");
        assertThat(planBody.get("occupancies").get(0).get("startUtc").asText()).isEqualTo(iso(8));
        assertThat(read(mvc.perform(get("/api/v1/plans/{key}/reschedule-records", p0))
                .andExpect(status().isOk()).andReturn())).isEmpty();

        // 失败不占键：撤销限速令（限速版本推进）后同键请求成功，按原时刻发布
        revokeOrder(orderKey);
        mvc.perform(post("/api/v1/plans/publish-batch")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(publishBatchBody(requestKey, null, p0)))
                .andExpect(status().isOk());
        assertThat(read(mvc.perform(get("/api/v1/plans/{key}", p0))
                .andExpect(status().isOk()).andReturn())
                .get("occupancies").get(0).get("startUtc").asText()).isEqualTo(iso(8));
    }

    @Test
    void withinBatchShiftConflictRejectsAndStableDetails() throws Exception {
        String section = registerSection(60_000);
        String p0 = key("SCH");
        String p1 = key("SCH");
        createPlan(p0, occ("G1", section, iso(8), iso(8, 40)));
        createPlan(p1, occ("G2", section, iso(8), iso(8, 40)));
        registerOrder(key("ORD"), section, iso(8), iso(10), 60);

        MvcResult fail = mvc.perform(post("/api/v1/plans/publish-batch")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(publishBatchBody(key("REQ"), null, p0, p1)))
                .andExpect(status().isUnprocessableEntity()).andReturn();
        JsonNode error = read(fail);
        assertThat(error.get("details").get(0).get("type").asText())
                .isEqualTo("BATCH_SHIFT_CONFLICT");
        assertThat(error.get("details").get(0).get("conflictingScheduleKey").asText())
                .isEqualTo(p0);

        for (String key : new String[]{p0, p1}) {
            assertThat(read(mvc.perform(get("/api/v1/plans/{key}", key))
                    .andExpect(status().isOk()).andReturn()).get("status").asText())
                    .isEqualTo("DRAFT");
        }
    }

    @Test
    void alreadyStartedPlanCannotRescheduleViaPublish() throws Exception {
        // 固定时钟到计划最早开始时刻 08:00：已开始运行不可重排，但限速令仍可登记
        clock.pinTo(DAY.atTime(8, 0).atZone(SH).toInstant());
        String section = registerSection(60_000);
        String plan = key("SCH");
        createPlan(plan, occ("G1", section, iso(8), iso(8, 40)));
        registerOrder(key("ORD"), section, iso(8), iso(10), 60);

        MvcResult fail = mvc.perform(post("/api/v1/plans/{key}/publish", plan)
                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(key("REQ"))))
                .andExpect(status().isUnprocessableEntity()).andReturn();
        JsonNode error = read(fail);
        assertThat(error.get("details").get(0).get("type").asText())
                .isEqualTo("PLAN_ALREADY_STARTED");
        // 计划保持草稿、原时刻不变、无重排记录
        assertThat(read(mvc.perform(get("/api/v1/plans/{key}", plan))
                .andExpect(status().isOk()).andReturn()).get("status").asText())
                .isEqualTo("DRAFT");
    }

    @Test
    void restrictionRegisteredAfterPublishOnlyAffectsLaterReschedule() throws Exception {
        String section = registerSection(60_000);
        String oldKey = key("SCH");
        createPlan(oldKey, occ("G1", section, iso(8), iso(9)));
        publishPlan(oldKey, key("REQ"));

        // 已发布计划之后登记限速令：已发布时刻不自动重排
        String orderKey = key("ORD");
        registerOrder(orderKey, section, iso(8), iso(10), 60);
        JsonNode oldSlots = read(mvc.perform(get("/api/v1/published-slots")
                        .param("date", DAY.toString()).param("sectionId", section))
                .andExpect(status().isOk()).andReturn());
        assertThat(oldSlots.get(0).get("startUtc").asText()).isEqualTo(iso(8));

        // 后续改签的新草稿违反限速：整体顺延后发布，旧计划取消且历史占用保留
        String newKey = key("SCH");
        createPlan(newKey, occ("G2", section, iso(8), iso(8, 40)));
        MvcResult result = mvc.perform(post("/api/v1/plans/{key}/reschedule", oldKey)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(rescheduleBody(key("REQ"), newKey, 1, 1)))
                .andExpect(status().isOk()).andReturn();
        JsonNode body = read(result);
        assertThat(body.get("oldPlan").get("status").asText()).isEqualTo("CANCELLED");
        assertThat(body.get("oldPlan").get("occupancies").get(0).get("startUtc").asText())
                .isEqualTo(iso(8));
        assertThat(body.get("newPlan").get("status").asText()).isEqualTo("PUBLISHED");
        assertThat(body.get("newPlan").get("occupancies").get(0).get("startUtc").asText())
                .isEqualTo(iso(10));

        JsonNode records = read(mvc.perform(get("/api/v1/plans/{key}/reschedule-records", newKey))
                .andExpect(status().isOk()).andReturn());
        assertThat(records).hasSize(1);
        assertThat(records.get(0).get("triggerOp").asText()).isEqualTo("RESCHEDULE");
        assertThat(records.get(0).get("recordKey").asText()).startsWith("RESCHEDULE:");

        // 再撤销限速令，证据与改签链不变
        revokeOrder(orderKey);
        JsonNode chain = read(mvc.perform(get("/api/v1/plans/{key}/reschedule-chain", newKey))
                .andExpect(status().isOk()).andReturn());
        assertThat(chain.get("chain")).hasSize(2);
        assertThat(read(mvc.perform(get("/api/v1/reschedule-records/{key}",
                        records.get(0).get("recordKey").asText()))
                .andExpect(status().isOk()).andReturn()).get("items").hasSize(1);
    }

    @Test
    void batchRescheduleShiftsNewDraftsAtomically() throws Exception {
        String s1 = registerSection(60_000);
        String s2 = registerSection(60_000);
        String oldA = key("SCH");
        String oldB = key("SCH");
        String newA = key("SCH");
        String newB = key("SCH");
        createPlan(oldA, occ("G1", s1, iso(8), iso(9)));
        createPlan(oldB, occ("G3", s2, iso(8), iso(9)));
        publishPlan(oldA, key("REQ"));
        publishPlan(oldB, key("REQ"));
        createPlan(newA, occ("G2", s1, iso(8), iso(8, 40)));
        createPlan(newB, occ("G4", s2, iso(9), iso(10)));
        registerOrder(key("ORD"), s1, iso(8), iso(10), 60);

        String body = rescheduleBatchBody(key("REQ"), "DISP-B",
                batchItem(oldA, newA), batchItem(oldB, newB));
        MvcResult result = mvc.perform(post("/api/v1/plans/reschedule-batch")
                        .contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isOk()).andReturn();
        JsonNode resp = read(result);
        assertThat(resp.get("maxDelayMinutes").asLong()).isEqualTo(120L);
        assertThat(resp.get("newDelays").get(0).asLong()).isEqualTo(120L);
        assertThat(resp.get("newDelays").get(1).asLong()).isEqualTo(120L);
        assertThat(resp.get("pairs").get(0).get("newPlan").get("occupancies").get(0)
                .get("startUtc").asText()).isEqualTo(iso(10));
        assertThat(resp.get("pairs").get(1).get("newPlan").get("occupancies").get(0)
                .get("startUtc").asText()).isEqualTo(iso(11));
        assertThat(resp.get("rescheduleRecordKey").asText())
                .startsWith("RESCHEDULE_BATCH:");

        assertThat(read(mvc.perform(get("/api/v1/plans/{key}", oldA))
                .andExpect(status().isOk()).andReturn()).get("status").asText())
                .isEqualTo("CANCELLED");
        assertThat(read(mvc.perform(get("/api/v1/plans/{key}", newB))
                .andExpect(status().isOk()).andReturn()).get("status").asText())
                .isEqualTo("PUBLISHED");
    }

    // ---------- 辅助 ----------

    private String registerSection(long lengthMeters) throws Exception {
        String section = key("SEC");
        mvc.perform(post("/api/v1/sections").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestKey\":\"" + key("REQ") + "\",\"sectionId\":\"" + section
                                + "\",\"sectionName\":\"测试区段\",\"lengthMeters\":" + lengthMeters
                                + "}"))
                .andExpect(status().isCreated());
        return section;
    }

    private void registerOrder(String orderKey, String section, String start, String end, int speed)
            throws Exception {
        mvc.perform(post("/api/v1/restrictions").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestKey\":\"" + key("REQ") + "\",\"orderKey\":\"" + orderKey
                                + "\",\"sectionId\":\"" + section + "\",\"startUtc\":\"" + start
                                + "\",\"endUtc\":\"" + end + "\",\"maxSpeedKmh\":" + speed + "}"))
                .andExpect(status().isCreated());
    }

    private void revokeOrder(String orderKey) throws Exception {
        mvc.perform(post("/api/v1/restrictions/{key}/revoke", orderKey)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestKey\":\"" + key("REQ") + "\"}"))
                .andExpect(status().isOk());
    }

    private void createPlan(String scheduleKey, String... occupancies) throws Exception {
        mvc.perform(post("/api/v1/plans").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"requestKey\":\"" + key("REQ") + "\",\"scheduleKey\":\""
                                + scheduleKey + "\",\"opDate\":\"" + DAY + "\",\"occupancies\":["
                                + String.join(",", occupancies) + "]}"))
                .andExpect(status().isCreated());
    }

    private void publishPlan(String scheduleKey, String requestKey) throws Exception {
        mvc.perform(post("/api/v1/plans/{key}/publish", scheduleKey)
                        .contentType(MediaType.APPLICATION_JSON).content(actionBody(requestKey)))
                .andExpect(status().isOk());
    }

    private JsonNode read(MvcResult result) throws Exception {
        return objectMapper.readTree(result.getResponse().getContentAsString());
    }

    private static String key(String prefix) {
        return prefix + "-" + UUID.randomUUID();
    }

    private static String iso(int hour) {
        return iso(hour, 0);
    }

    private static String iso(int hour, int minute) {
        Instant instant = DAY.atTime(hour, minute).atZone(SH).toInstant();
        return instant.toString();
    }

    private static String occ(String train, String section, String start, String end) {
        return "{\"trainNo\":\"" + train + "\",\"sectionId\":\"" + section
                + "\",\"startUtc\":\"" + start + "\",\"endUtc\":\"" + end + "\"}";
    }

    private static String actionBody(String requestKey) {
        return "{\"requestKey\":\"" + requestKey + "\"}";
    }

    private static String publishBatchBody(String requestKey, String operator, String... keys) {
        String array = String.join(",", java.util.Arrays.stream(keys)
                .map(k -> "\"" + k + "\"").toList());
        return "{\"requestKey\":\"" + requestKey + "\""
                + (operator == null ? "" : ",\"operator\":\"" + operator + "\"")
                + ",\"scheduleKeys\":[" + array + "]}";
    }

    private static String batchItem(String oldKey, String newKey) {
        return "{\"oldScheduleKey\":\"" + oldKey + "\",\"newScheduleKey\":\"" + newKey
                + "\",\"expectedOldVersion\":1,\"expectedNewVersion\":1}";
    }

    private static String rescheduleBatchBody(String requestKey, String operator, String... items) {
        return "{\"requestKey\":\"" + requestKey + "\",\"operator\":\"" + operator
                + "\",\"items\":[" + String.join(",", items) + "]}";
    }

    private static String rescheduleBody(String requestKey, String newKey, int oldV, int newV) {
        return "{\"requestKey\":\"" + requestKey + "\",\"newScheduleKey\":\"" + newKey
                + "\",\"expectedOldVersion\":" + oldV + ",\"expectedNewVersion\":" + newV + "}";
    }
}

