package com.example.starter.plan;

import static org.assertj.core.api.Assertions.assertThat;

import com.example.starter.plan.service.PlanService;
import com.example.starter.plan.service.RailClock;
import com.example.starter.plan.service.RestrictionService;
import com.example.starter.plan.web.dto.CreatePlanRequest;
import com.example.starter.plan.web.dto.OccupancyRequest;
import com.example.starter.plan.web.dto.PlanResponse;
import com.example.starter.plan.web.dto.PublishBatchRequest;
import com.example.starter.plan.web.dto.RescheduleRequest;
import com.example.starter.plan.web.dto.RestrictionRegisterRequest;
import java.time.Instant;
import java.time.LocalDate;
import java.time.ZoneId;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 气象限速与计划发布/改签的并发裁决测试（H2 内存库，真实线程）：
 * 登记与发布按全局锁提交顺序裁决；并发改签与限速登记只产生一套生效时刻；
 * 同键并发登记返回同一首次结果。
 */
@SpringBootTest
class WeatherRescheduleConcurrencyTest {

    private static final ZoneId SH = ZoneId.of("Asia/Shanghai");
    private static final LocalDate DAY = LocalDate.of(2026, 9, 22);

    @Autowired
    private PlanService planService;

    @Autowired
    private RestrictionService restrictionService;

    @Autowired
    private RailClock clock;

    @Autowired
    private JdbcTemplate jdbc;

    @BeforeEach
    void pinClock() {
        clock.pinTo(DAY.atTime(7, 0).atZone(SH).toInstant());
    }

    @AfterEach
    void resetClock() {
        clock.reset();
    }

    @Test
    void concurrentRegisterAndPublishAreOrderedByCommit() throws Exception {
        String section = registerSection(60_000);
        String plan = key("SCH");
        createDraft(plan, section, 8, 0, 8, 40);
        String orderKey = key("ORD");

        List<Object> outcomes = runConcurrently(List.of(
                () -> {
                    restrictionService.register(new RestrictionRegisterRequest(
                            key("REQ"), orderKey, section, at(8), at(10), 60, "DISP"));
                    return "REGISTERED";
                },
                () -> {
                    planService.publish(plan, key("REQ"));
                    return "PUBLISHED";
                }));
        assertThat(outcomes).containsExactlyInAnyOrder("REGISTERED", "PUBLISHED");

        // 两种提交顺序都自洽：发布先于登记则保持 08:00 且无重排记录；
        // 登记先于发布则整体顺延至 10:00 且有证据。
        PlanResponse finalPlan = planService.getPlan(plan);
        assertThat(finalPlan.status()).isEqualTo("PUBLISHED");
        Instant start = finalPlan.occupancies().get(0).startUtc();
        assertThat(start).isIn(at(8), at(10));
        long recordCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM rail_reschedule_item i WHERE i.schedule_key = ?",
                Long.class, plan);
        if (start.equals(at(10))) {
            assertThat(recordCount).isEqualTo(1L);
        } else {
            assertThat(recordCount).isZero();
        }
        // 无论顺序如何，限速令最终存在且版本为 1
        assertThat(restrictionService.getOrderDetail(orderKey)).hasSize(1);
    }

    @Test
    void concurrentRescheduleAndRegisterProduceSingleEffectiveTimeline() throws Exception {
        String section = registerSection(60_000);
        String oldKey = key("SCH");
        String newKey = key("SCH");
        createDraft(oldKey, section, 8, 0, 9, 0);
        planService.publish(oldKey, key("REQ"));
        createDraft(newKey, section, 8, 0, 8, 40);
        String orderKey = key("ORD");

        List<Object> outcomes = runConcurrently(List.of(
                () -> {
                    planService.reschedule(oldKey, new RescheduleRequest(
                            key("REQ"), newKey, 1, 1));
                    return "RESCHEDULED";
                },
                () -> {
                    restrictionService.register(new RestrictionRegisterRequest(
                            key("REQ"), orderKey, section, at(8), at(10), 60, "DISP"));
                    return "REGISTERED";
                }));
        assertThat(outcomes).containsExactlyInAnyOrder("RESCHEDULED", "REGISTERED");

        // 旧计划恰好取消一次，新计划恰好发布一次，只有一套生效时刻
        assertThat(planService.getPlan(oldKey).status()).isEqualTo("CANCELLED");
        PlanResponse successor = planService.getPlan(newKey);
        assertThat(successor.status()).isEqualTo("PUBLISHED");
        Instant start = successor.occupancies().get(0).startUtc();
        assertThat(start).isIn(at(8), at(10));

        long linkCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM rail_plan_reschedule_link l"
                        + " JOIN rail_day_plan p ON p.id = l.successor_plan_id"
                        + " WHERE p.schedule_key = ?",
                Long.class, newKey);
        assertThat(linkCount).isEqualTo(1L);

        long itemCount = jdbc.queryForObject(
                "SELECT COUNT(*) FROM rail_reschedule_item i WHERE i.schedule_key = ?",
                Long.class, newKey);
        // 改签先提交：无顺延无证据；登记先提交：顺延 120 分钟且有证据
        if (start.equals(at(10))) {
            assertThat(itemCount).isEqualTo(1L);
        } else {
            assertThat(itemCount).isZero();
        }
    }

    @Test
    void concurrentSameKeyRegisterReturnsSingleFirstResult() throws Exception {
        String section = registerSection(60_000);
        String orderKey = key("ORD");
        String requestKey = key("REQ");
        int threads = 4;

        List<Callable<Object>> tasks = new ArrayList<>();
        for (int i = 0; i < threads; i++) {
            tasks.add(() -> restrictionService.register(new RestrictionRegisterRequest(
                    requestKey, orderKey, section, at(8), at(10), 60, "DISP")));
        }
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch ready = new CountDownLatch(threads);
        CountDownLatch go = new CountDownLatch(1);
        List<Future<Object>> futures = tasks.stream()
                .map(t -> pool.submit(() -> {
                    ready.countDown();
                    go.await();
                    return t.call();
                })).toList();
        ready.await();
        go.countDown();
        List<Object> views = new ArrayList<>();
        for (Future<Object> f : futures) {
            views.add(f.get(30, TimeUnit.SECONDS));
        }
        pool.shutdown();

        assertThat(views).allMatch(v -> v.equals(views.get(0)));
        Long versionRows = jdbc.queryForObject(
                "SELECT COUNT(*) FROM speed_restriction_order WHERE order_key = ?",
                Long.class, orderKey);
        assertThat(versionRows).isEqualTo(1L);
    }

    @Test
    void concurrentBatchPublishWithInterleavingRegisterIsSerializable() throws Exception {
        String section = registerSection(60_000);
        String p0 = key("SCH");
        String p1 = key("SCH");
        createDraft(p0, section, 8, 0, 8, 40);
        createDraft(p1, section, 9, 0, 10, 0);
        String orderKey = key("ORD");

        List<Object> outcomes = runConcurrently(List.of(
                () -> {
                    planService.publishBatch(new PublishBatchRequest(
                            key("REQ"), "DISP", List.of(p0, p1)));
                    return "BATCH";
                },
                () -> {
                    restrictionService.register(new RestrictionRegisterRequest(
                            key("REQ"), orderKey, section, at(8), at(10), 60, "DISP"));
                    return "REGISTERED";
                }));
        assertThat(outcomes).containsExactlyInAnyOrder("BATCH", "REGISTERED");

        // 批量与登记互斥：批要么全在登记前（两计划均原时刻），要么全在登记后
        // （p0 顺延 120，p1 因批内传递也顺延 120 且不与 p0 冲突）
        PlanResponse a = planService.getPlan(p0);
        PlanResponse b = planService.getPlan(p1);
        assertThat(a.status()).isEqualTo("PUBLISHED");
        assertThat(b.status()).isEqualTo("PUBLISHED");
        Instant a0 = a.occupancies().get(0).startUtc();
        Instant b0 = b.occupancies().get(0).startUtc();
        if (a0.equals(at(10))) {
            assertThat(b0).isEqualTo(at(11));
        } else {
            assertThat(a0).isEqualTo(at(8));
            assertThat(b0).isEqualTo(at(9));
        }
    }

    // ---------- 辅助 ----------

    private String registerSection(long lengthMeters) {
        restrictionService.registerSection(new com.example.starter.plan.web.dto.RegisterSectionRequest(
                key("REQ"), key("SEC"), "并发测试区段", lengthMeters));
        String section = jdbc.queryForObject(
                "SELECT section_id FROM rail_section ORDER BY id DESC LIMIT 1", String.class);
        return section;
    }

    private void createDraft(String scheduleKey, String section, int sh, int sm, int eh, int em) {
        planService.createDraft(new CreatePlanRequest(key("REQ"), scheduleKey, DAY,
                List.of(new OccupancyRequest("G-" + UUID.randomUUID(), section,
                        at(sh, sm), at(eh, em)))));
    }

    private List<Object> runConcurrently(List<Callable<Object>> tasks) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(tasks.size());
        CountDownLatch ready = new CountDownLatch(tasks.size());
        CountDownLatch go = new CountDownLatch(1);
        List<Future<Object>> futures = tasks.stream()
                .map(t -> pool.submit(() -> {
                    ready.countDown();
                    go.await();
                    return t.call();
                })).toList();
        ready.await();
        go.countDown();
        List<Object> outcomes = new ArrayList<>();
        for (Future<Object> f : futures) {
            outcomes.add(f.get(30, TimeUnit.SECONDS));
        }
        pool.shutdown();
        return outcomes;
    }

    private static Instant at(int hour) {
        return at(hour, 0);
    }

    private static Instant at(int hour, int minute) {
        return DAY.atTime(hour, minute).atZone(SH).toInstant();
    }

    private static String key(String prefix) {
        return prefix + "-" + UUID.randomUUID();
    }
}

